package com.loosechange;

import lombok.RequiredArgsConstructor;

/** How items worth more alched than sold are marked (Alch Tag). */
@RequiredArgsConstructor
public enum AlchMark
{
	OFF("Off"),
	ICON("Icon"),
	LABEL("Text");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.loosechange;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.game.SpriteOverride;

/**
 * The bank button's icon: the plugin's own coin pile, given to the game as
 * sprites under ids of our own, drawn at two sizes so it's never scaled. The button uses the
 * biggest that fits beside the bank's tutorial button.
 */
@Getter
@RequiredArgsConstructor
enum BankButtonIcon implements SpriteOverride
{
	LARGE(-27_402, "bank_button_24.png", 24),
	/** The sidebar icon's pixels. */
	SMALL(-27_401, "bank_button_16.png", 16);

	/** Negative, so it can't be a game sprite. */
	private final int spriteId;
	private final String fileName;
	/** Width and height in pixels. */
	private final int size;

	/** Whether a widget's sprite is one of these: a bank button this plugin made. */
	static boolean isOurs(int spriteId)
	{
		for (BankButtonIcon icon : values())
		{
			if (icon.spriteId == spriteId)
			{
				return true;
			}
		}
		return false;
	}

	/** The biggest icon no taller than {@code room}, or the small one if none is. */
	static BankButtonIcon fitting(int room)
	{
		return room >= LARGE.size ? LARGE : SMALL;
	}
}

package com.loosechange;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;

/**
 * The last bank seen, kept per account so the sidebar works with the bank
 * closed and after a restart: the whole bank, since Entire Bank lists every
 * stack. Saved as "id:quantity" pairs.
 */
final class BankCopy
{
	private BankCopy()
	{
	}

	/**
	 * Merges a bank's stacks under their canonical ids (unnoted), and drops
	 * empty slots and placeholders. A placeholder is told by its item
	 * definition, not its quantity: the bank can report one with a quantity,
	 * which would list an item the player doesn't have.
	 */
	static Map<Integer, Integer> canonical(int[] ids, int[] quantities, IntUnaryOperator canonicalize, IntPredicate isPlaceholder)
	{
		Map<Integer, Integer> bank = new LinkedHashMap<>();
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] <= 0 || quantities[i] <= 0)
			{
				continue;
			}
			if (isPlaceholder.test(ids[i]))
			{
				continue;
			}
			bank.merge(canonicalize.applyAsInt(ids[i]), quantities[i], BankCopy::addCapped);
		}
		return bank;
	}

	private static int addCapped(int a, int b)
	{
		long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}

	static String encode(Map<Integer, Integer> bank)
	{
		StringBuilder sb = new StringBuilder(bank.size() * 10);
		for (Map.Entry<Integer, Integer> e : bank.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(e.getKey()).append(':').append(e.getValue());
		}
		return sb.toString();
	}

	/** Null when nothing was saved. Bad entries are skipped. */
	static Map<Integer, Integer> decode(String saved)
	{
		if (saved == null || saved.isEmpty())
		{
			return null;
		}
		Map<Integer, Integer> bank = new LinkedHashMap<>();
		for (String entry : saved.split(","))
		{
			int colon = entry.indexOf(':');
			if (colon <= 0)
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(entry.substring(0, colon));
				int quantity = Integer.parseInt(entry.substring(colon + 1));
				if (quantity > 0)
				{
					bank.put(id, quantity);
				}
			}
			catch (NumberFormatException ignored)
			{
				// skip it
			}
		}
		return bank;
	}
}

package com.loosechange;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Value;

/**
 * The bank view's slot order, as a Bank Tags layout: item ids by slot, -1
 * for an empty slot. Items for sale come first, in the Sort By order. By
 * boss or by type, each group gets a titled row and its items below. Kept
 * items follow under a "Keep" title. A title takes one empty row; the plugin
 * draws its text.
 *
 * Each item takes one slot: a bank item can only be drawn once, and Bank
 * Tags shows any repeat as a faded placeholder. So by boss, an item goes
 * under the one boss Shared Drops picks (as in the sidebar), and a part-kept
 * stack stays with the items for sale rather than showing again under Kept.
 */
final class BankLayout
{
	/** Items per bank row. */
	static final int ROW = 8;

	/** A title row's {@link Header#getValue()} when it has no total (Kept). */
	static final long NO_VALUE = -1;

	/** A titled empty row: where it starts (slot index), its title, and the group's total or {@link #NO_VALUE}. */
	@Value
	static class Header
	{
		int slot;
		String text;
		long value;
	}

	@Value
	static class Plan
	{
		int[] slots;
		List<Header> headers;
	}

	private BankLayout()
	{
	}

	/**
	 * @param maxSlots the bank's item slots; Bank Tags fails on a longer
	 *                 layout. Groups fall back to the plain list when they
	 *                 don't fit, and anything still past the end is cut.
	 */
	static Plan build(SellList.Result result, GroupBy by, SharedItems shared, int maxSlots)
	{
		boolean grouped = by != GroupBy.NONE;
		Plan plan = grouped ? grouped(result, by, shared) : list(result);
		if (grouped && plan.getSlots().length > maxSlots)
		{
			plan = list(result);
		}
		return plan.getSlots().length > maxSlots ? cut(plan, maxSlots) : plan;
	}

	/** Whole bank mode: every priced stack in one list, no titles, cut at the bank's item slots. */
	static Plan whole(BankWorth.Result worth, int maxSlots)
	{
		List<Integer> slots = new ArrayList<>();
		for (BankWorth.Row row : worth.getRows())
		{
			slots.add(row.getItemId());
		}
		while (slots.size() % ROW != 0)
		{
			slots.add(-1);
		}
		Plan plan = plan(slots, new ArrayList<>());
		return plan.getSlots().length > maxSlots ? cut(plan, maxSlots) : plan;
	}

	private static Plan list(SellList.Result result)
	{
		List<Integer> slots = new ArrayList<>();
		List<Header> headers = new ArrayList<>();
		addRows(slots, result.getSellable());
		addKept(slots, headers, result);
		return plan(slots, headers);
	}

	private static Plan grouped(SellList.Result result, GroupBy by, SharedItems shared)
	{
		List<Integer> slots = new ArrayList<>();
		List<Header> headers = new ArrayList<>();
		for (SellList.Group group : result.groups(by, shared))
		{
			header(slots, headers, PanelStyle.groupTitle(group.getTitle()), group.getValue());
			addRows(slots, group.getRows());
		}
		addKept(slots, headers, result);
		return plan(slots, headers);
	}

	/** Fully kept stacks; part-kept ones are already listed for sale. */
	private static void addKept(List<Integer> slots, List<Header> headers, SellList.Result result)
	{
		Set<Integer> listed = new HashSet<>();
		for (SellList.Row row : result.getSellable())
		{
			listed.add(row.getItemId());
		}
		List<SellList.Row> kept = new ArrayList<>();
		for (SellList.Row row : result.getKept())
		{
			if (!listed.contains(row.getItemId()))
			{
				kept.add(row);
			}
		}
		if (!kept.isEmpty())
		{
			header(slots, headers, "Keep (" + kept.size() + ")", NO_VALUE);
			addRows(slots, kept);
		}
	}

	/** The first {@code max} slots, and the titles whose rows are still in them. */
	private static Plan cut(Plan plan, int max)
	{
		int[] slots = new int[Math.max(0, max)];
		System.arraycopy(plan.getSlots(), 0, slots, 0, slots.length);
		List<Header> headers = new ArrayList<>();
		for (Header h : plan.getHeaders())
		{
			if (h.getSlot() + ROW <= slots.length)
			{
				headers.add(h);
			}
		}
		return new Plan(slots, Collections.unmodifiableList(headers));
	}

	private static Plan plan(List<Integer> slots, List<Header> headers)
	{
		int[] layout = new int[slots.size()];
		for (int i = 0; i < layout.length; i++)
		{
			layout[i] = slots.get(i);
		}
		return new Plan(layout, Collections.unmodifiableList(headers));
	}

	/** One empty row whose slot the title is drawn over. */
	private static void header(List<Integer> slots, List<Header> headers, String text, long value)
	{
		headers.add(new Header(slots.size(), text, value));
		for (int i = 0; i < ROW; i++)
		{
			slots.add(-1);
		}
	}

	/** The items from {@code rows}, then empty slots to the end of the row. */
	private static void addRows(List<Integer> slots, List<SellList.Row> rows)
	{
		for (SellList.Row row : rows)
		{
			slots.add(row.getItemId());
		}
		while (slots.size() % ROW != 0)
		{
			slots.add(-1);
		}
	}
}

package com.loosechange;

import java.awt.Color;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.util.ColorUtil;

/**
 * The sellable items (or, in Entire Bank mode, every priced stack) as a view
 * of the real bank, through the core Bank Tags plugin: a registered tag (no
 * tab, nothing written to the player's tags) opened from a small button on
 * the bank, laid out in the Sort By order. The only
 * thing saved is the layout of this plugin's own tag, removed on shutdown.
 * Everything here runs on the client thread.
 */
@Singleton
class BankView
{
	/** Space between the bank's tutorial button and ours. */
	private static final int BUTTON_GAP = 3;
	/** A title row's height: a bank slot's, less a little (see drawHeaders). */
	private static final int HEADER_HEIGHT = 30;
	/** A bank item slot's height. */
	private static final int ITEM_HEIGHT = 32;
	/** The bank's orange title text, and the dim rules either side of it. */
	private static final int HEADER_COLOR = 0xff981f;
	private static final int LINE_COLOR = 0x5a5245;
	/** The rules sit level with the middle of the title's capitals, this far below the row's top. */
	private static final int LINE_Y = 17;
	/** Space between a title and its rules. */
	private static final int LINE_GAP = 6;
	/** The bank button's see-through amount while the view is closed (0 = solid, 255 = gone). */
	private static final int BUTTON_DIM = 60;
	/**
	 * The Bank Tag Layouts hub plugin lays out every tag when its "Enable
	 * layout by default" is on, keeping its own slot for each item, which
	 * overrides this view's order. It leaves alone a tag whose key holds its
	 * "disabled" marker, the same as its own Disable layout menu.
	 */
	private static final String LAYOUTS_PLUGIN_GROUP = "banktaglayouts";
	private static final String LAYOUTS_PLUGIN_KEY = "layout_" + Names.BANK_TAG;
	private static final String LAYOUTS_PLUGIN_DISABLED = "DISABLED";
	/**
	 * Bank Tags saves the last tag opened here (BankTagsConfig.tab) and opens
	 * it with the bank when Remember last tag tab is on.
	 */
	private static final String BANK_TAGS_GROUP = "banktags";
	private static final String BANK_TAGS_LAST_TAB = "tab";
	/** How the view's title starts ({@link #title}); dropped when the title would run under the button. */
	private static final String TITLE_START = Names.DISPLAY + " · ";

	private final Client client;
	private final ItemManager itemManager;
	private final TagManager tagManager;
	private final BankTagsService bankTags;
	private final LayoutManager layoutManager;
	private final ConfigManager configManager;
	private final SpriteManager spriteManager;

	/** Canonical ids in the open view, fixed when it opens so withdrawing doesn't reshuffle it. */
	private volatile Set<Integer> shown = Set.of();
	/** The open view's titled rows. */
	private List<BankLayout.Header> headers = List.of();
	/** Title texts and lines drawn over the bank's item grid, reused between builds. */
	private final List<Widget> headerText = new ArrayList<>();
	private final List<Widget> headerLine = new ArrayList<>();
	private Widget button;
	/** The title's leading "Loose Change · " is dropped to clear the button ({@link #fitTitle}). */
	private boolean titleShortened;

	@Inject
	BankView(Client client, ItemManager itemManager, TagManager tagManager, BankTagsService bankTags, LayoutManager layoutManager,
		ConfigManager configManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.tagManager = tagManager;
		this.bankTags = bankTags;
		this.layoutManager = layoutManager;
		this.configManager = configManager;
		this.spriteManager = spriteManager;
	}

	void startUp()
	{
		// The bank button's icon, as sprites of our own (again after a profile switch is harmless).
		spriteManager.addSpriteOverrides(BankButtonIcon.values());
		tagManager.registerTag(Names.BANK_TAG, itemId -> shown.contains(itemManager.canonicalize(itemId)));
		configManager.setConfiguration(LAYOUTS_PLUGIN_GROUP, LAYOUTS_PLUGIN_KEY, LAYOUTS_PLUGIN_DISABLED);
	}

	void shutDown()
	{
		if (isOpen())
		{
			bankTags.closeBankTag();
		}
		// Turned off with the bank closed on the view: Bank Tags would reopen this
		// tag with the next bank, empty once unregistered. The normal bank instead.
		forgetLastTab();
		tagManager.unregisterTag(Names.BANK_TAG);
		layoutManager.removeLayout(Names.BANK_TAG);
		configManager.unsetConfiguration(LAYOUTS_PLUGIN_GROUP, LAYOUTS_PLUGIN_KEY);
		removeWidgets();
		spriteManager.removeSpriteOverrides(BankButtonIcon.values());
	}

	/**
	 * The next bank opens on the normal bank, not the view: Bank Tags forgets
	 * the view as its last tag. A tag of the player's own is left alone.
	 */
	void forgetLastTab()
	{
		if (Names.BANK_TAG.equals(configManager.getConfiguration(BANK_TAGS_GROUP, BANK_TAGS_LAST_TAB)))
		{
			configManager.unsetConfiguration(BANK_TAGS_GROUP, BANK_TAGS_LAST_TAB);
		}
	}

	boolean isOpen()
	{
		return Names.BANK_TAG.equals(bankTags.getActiveTag());
	}

	boolean isBankOpen()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return client.getItemContainer(InventoryID.BANK) != null && items != null && !items.isHidden();
	}

	/** Opens the view with this layout, or lays it out again if it's open. Needs the bank open. */
	void open(BankLayout.Plan plan)
	{
		int[] layout = plan.getSlots();
		headers = plan.getHeaders();
		Set<Integer> ids = new HashSet<>();
		for (int id : layout)
		{
			if (id > 0)
			{
				ids.add(id);
			}
		}
		shown = ids;
		layoutManager.saveLayout(new Layout(Names.BANK_TAG, layout));
		bankTags.openBankTag(Names.BANK_TAG, BankTagsService.OPTION_HIDE_TAG_NAME);
	}

	/**
	 * The bank's item slots: its first children, all item-sized graphics
	 * (1,410 today). Tab lines and this plugin's titles follow them. Bank
	 * Tags draws layout slot N into child N, so a longer layout would draw
	 * items into those and then fail.
	 */
	int itemSlots()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		Widget[] children = items == null ? null : items.getChildren();
		if (children == null)
		{
			return 0;
		}
		int n = 0;
		while (n < children.length && children[n] != null
			&& children[n].getType() == WidgetType.GRAPHIC
			&& children[n].getOriginalHeight() >= ITEM_HEIGHT)
		{
			n++;
		}
		return n;
	}

	void close()
	{
		if (isOpen())
		{
			bankTags.closeBankTag();
		}
	}

	/** A fresh bank interface: its old widgets are gone. */
	void onBankLoaded()
	{
		button = null;
		titleShortened = false;
		headerText.clear();
		headerLine.clear();
	}

	/** After the bank is drawn: the title while the view is open, and the button (if shown). */
	void onBankBuilt(String title, boolean hidePlaceholders, boolean showButton, Runnable onButton)
	{
		updateTitle(title);
		if (hidePlaceholders)
		{
			hidePlaceholders();
		}
		drawHeaders();
		setButtonShown(showButton, onButton);
	}

	/**
	 * Adds or takes away the bank button (Bank Button setting). Needs the
	 * bank open. Goes by the buttons really in the title bar, not only the one
	 * remembered: one left from an earlier bank build is hidden too, so
	 * unticking the setting always takes the button away.
	 */
	void setButtonShown(boolean show, Runnable onButton)
	{
		List<Widget> ours = buttonsInBank();
		Widget keep = null;
		if (show)
		{
			keep = ours.contains(button) ? button : ours.isEmpty() ? null : ours.get(0);
		}
		for (Widget w : ours)
		{
			if (w != keep)
			{
				w.setHidden(true);
			}
		}
		if (show && keep == null)
		{
			keep = createButton(onButton);
		}
		button = keep;
		if (button != null)
		{
			button.setAction(0, isOpen() ? "Close" : "Show");
			// Lit while the view is open, dim while it's closed.
			button.setOpacity(isOpen() ? 0 : BUTTON_DIM);
		}
		fitTitle();
	}

	/** This plugin's buttons showing in the bank's title bar, told by their sprites (ids only this plugin uses). */
	private List<Widget> buttonsInBank()
	{
		List<Widget> out = new ArrayList<>();
		Widget tutorial = client.getWidget(InterfaceID.Bankmain.BANK_TUT);
		Widget[] children = tutorial == null || tutorial.getParent() == null ? null : tutorial.getParent().getDynamicChildren();
		if (children == null)
		{
			return out;
		}
		for (Widget w : children)
		{
			if (w != null && !w.isHidden() && BankButtonIcon.isOurs(w.getSpriteId()))
			{
				out.add(w);
			}
		}
		return out;
	}

	/** The bank title shows the total while the view is open. */
	void updateTitle(String text)
	{
		if (!isOpen())
		{
			return;
		}
		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (title != null)
		{
			title.setText(text);
			titleShortened = false;
			fitTitle();
		}
	}

	/**
	 * Keeps the title clear of the bank button: when the centred title would
	 * run under it (a long search, or another plugin adding to the title,
	 * such as RuneLite's Bank plugin with the value of what's shown), the
	 * title drops its leading "Loose Change · ". The button's coin pile marks
	 * the view as this plugin's. Run once other plugins have written their
	 * part of the title.
	 */
	void fitTitle()
	{
		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		String text = title == null ? null : title.getText();
		if (!isOpen() || text == null || title.getFont() == null)
		{
			return;
		}
		if (titleShortened)
		{
			// Back in full once it fits again (the button taken away, say).
			String full = TITLE_START + text;
			if (!runsUnderButton(title, full))
			{
				title.setText(full);
				titleShortened = false;
			}
		}
		else if (text.startsWith(TITLE_START) && runsUnderButton(title, text))
		{
			title.setText(text.substring(TITLE_START.length()));
			titleShortened = true;
		}
	}

	/** Whether {@code text}, centred in the title, would reach the button (with a gap either side); never without one. */
	private boolean runsUnderButton(Widget title, String text)
	{
		if (button == null || button.isHidden())
		{
			return false;
		}
		Rectangle t = title.getBounds();
		Rectangle b = button.getBounds();
		if (t == null || b == null || b.width <= 0)
		{
			return false;
		}
		int width = title.getFont().getTextWidth(text);
		int left = t.x + (t.width - width) / 2;
		int right = left + width;
		return left < b.x + b.width + BUTTON_GAP && right > b.x - BUTTON_GAP;
	}

	/**
	 * The view's title, the total in the game's coin colour: "Loose
	 * Change · 6.6M · 32 slots" for what's for sale, "Loose Change · Entire
	 * Bank · 48.5M" for what the whole bank is worth. While Search Bank View
	 * cuts the view to a sidebar search, the search ends it in quotes (up to
	 * 12 letters), so a search left in the sidebar doesn't read as items gone
	 * missing. The totals stay the whole list's.
	 */
	static String title(ListMode mode, SellList.Result result, BankWorth.Result worth, String search)
	{
		String searched = search.isEmpty() ? "" : " · \"" + (search.length() > 12 ? search.substring(0, 12) + "..." : search) + "\"";
		if (mode == ListMode.WHOLE_BANK)
		{
			long total = worth.getTotalValue();
			return TITLE_START + mode + " · " + ColorUtil.wrapWithColorTag(Gp.format(total), coinColor(total)) + searched;
		}
		long total = result.getTotalValue();
		int slots = result.getSlotsFreed();
		return TITLE_START + ColorUtil.wrapWithColorTag(Gp.format(total), coinColor(total))
			+ " · " + slots + (slots == 1 ? " slot" : " slots") + searched;
	}

	/**
	 * Slots in the view with nothing to withdraw: the bank's own placeholders
	 * (told by their item definition; their quantity isn't reliably 0) and
	 * Bank Tags' layout placeholders for items no longer in
	 * the bank (quantity drawn as "never"). Hidden where they are, so
	 * withdrawing a stack leaves a gap rather than moving the next item
	 * under the cursor; the next layout closes the gaps.
	 */
	private void hidePlaceholders()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (!isOpen() || items == null)
		{
			return;
		}
		int slots = itemSlots();
		for (int i = 0; i < slots; i++)
		{
			Widget c = items.getChild(i);
			if (c != null && c.getItemId() > 0 && !c.isSelfHidden()
				&& (c.getItemQuantity() <= 0 || c.getItemQuantity() == Integer.MAX_VALUE
				|| itemManager.getItemComposition(c.getItemId()).getPlaceholderTemplateId() != -1))
			{
				c.setHidden(true);
			}
		}
	}

	/**
	 * Titles over the view's empty title rows ("Keep", and each boss or type
	 * when grouped), placed from the bank's own slot widgets after Bank Tags
	 * has laid them out, so they scroll with the items. Each title is centred
	 * between two rules, its total in the game's coin colour. Heights
	 * stay under a bank slot's 32 so Bank Tags never takes them for item slots.
	 */
	private void drawHeaders()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		List<BankLayout.Header> titles = isOpen() ? headers : List.of();
		int drawn = 0;
		if (items != null)
		{
			for (BankLayout.Header h : titles)
			{
				Widget first = items.getChild(h.getSlot());
				Widget last = items.getChild(h.getSlot() + BankLayout.ROW - 1);
				if (first == null || last == null)
				{
					continue;
				}
				int x = first.getOriginalX();
				int y = first.getOriginalY();
				int width = last.getOriginalX() + last.getOriginalWidth() - x;

				String value = h.getValue() == BankLayout.NO_VALUE ? "" : "  " + Gp.format(h.getValue());
				Widget text = pooled(headerText, drawn, items, WidgetType.TEXT);
				text.setText(h.getText() + (value.isEmpty() ? "" : ColorUtil.wrapWithColorTag(value, coinColor(h.getValue()))));
				text.setFontId(FontID.BOLD_12);
				text.setTextColor(HEADER_COLOR);
				text.setTextShadowed(true);
				text.setXTextAlignment(WidgetTextAlignment.CENTER);
				text.setYTextAlignment(WidgetTextAlignment.BOTTOM);
				place(text, x, y, width, HEADER_HEIGHT - 6);

				// The rules run from each end of the row to just short of the words.
				int words = textWidth(text, h.getText() + value);
				int side = Math.max(0, (width - words) / 2 - LINE_GAP);
				line(pooled(headerLine, drawn * 2, items, WidgetType.RECTANGLE), x, y + LINE_Y, side);
				line(pooled(headerLine, drawn * 2 + 1, items, WidgetType.RECTANGLE), x + width - side, y + LINE_Y, side);
				drawn++;
			}
		}
		hideFrom(headerText, drawn);
		hideFrom(headerLine, drawn * 2);
	}

	private static void line(Widget line, int x, int y, int width)
	{
		line.setTextColor(LINE_COLOR);
		line.setFilled(true);
		place(line, x, y, width, 1);
		line.setHidden(width <= 0);
	}

	/** The title's width in its font; a fair guess before the font is loaded. */
	private static int textWidth(Widget text, String plain)
	{
		FontTypeFace font = text.getFont();
		return font != null ? font.getTextWidth(plain) : plain.length() * 7;
	}

	/** The game's colours for coin stacks: yellow below 100k, white below 10m, green from 10m. */
	static Color coinColor(long gp)
	{
		return gp < 100_000 ? Color.YELLOW : gp < 10_000_000 ? Color.WHITE : new Color(0x00ff80);
	}

	private static Widget pooled(List<Widget> pool, int i, Widget parent, int type)
	{
		if (i < pool.size())
		{
			return pool.get(i);
		}
		Widget w = parent.createChild(-1, type);
		pool.add(w);
		return w;
	}

	private static void place(Widget w, int x, int y, int width, int height)
	{
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setOriginalWidth(width);
		w.setOriginalHeight(height);
		w.setHidden(false);
		w.revalidate();
	}

	private static void hideFrom(List<Widget> pool, int from)
	{
		for (int i = from; i < pool.size(); i++)
		{
			pool.get(i).setHidden(true);
		}
	}

	/** Right of the bank's tutorial button, in the title bar. */
	private Widget createButton(Runnable onClick)
	{
		Widget tutorial = client.getWidget(InterfaceID.Bankmain.BANK_TUT);
		if (tutorial == null || tutorial.getParent() == null)
		{
			return null;
		}
		int size = tutorial.getOriginalHeight();
		int x = tutorial.getXPositionMode() == WidgetPositionMode.ABSOLUTE_RIGHT
			? tutorial.getOriginalX() - size - BUTTON_GAP
			: tutorial.getOriginalX() + tutorial.getOriginalWidth() + BUTTON_GAP;

		// The plugin's coin pile at its own pixels (never scaled), centred in
		// a square the size of the tutorial button.
		BankButtonIcon icon = BankButtonIcon.fitting(size);
		int inset = Math.max(0, (size - icon.getSize()) / 2);
		Widget w = tutorial.getParent().createChild(-1, WidgetType.GRAPHIC);
		w.setSpriteId(icon.getSpriteId());
		w.setOriginalWidth(icon.getSize());
		w.setOriginalHeight(icon.getSize());
		w.setXPositionMode(tutorial.getXPositionMode());
		w.setYPositionMode(tutorial.getYPositionMode());
		w.setOriginalX(tutorial.getXPositionMode() == WidgetPositionMode.ABSOLUTE_CENTER ? x : x + inset);
		w.setOriginalY(tutorial.getYPositionMode() == WidgetPositionMode.ABSOLUTE_CENTER
			? tutorial.getOriginalY() : tutorial.getOriginalY() + inset);
		w.setName("<col=ff9040>" + Names.DISPLAY + "</col>");
		w.setAction(0, "Show");
		w.setHasListener(true);
		w.setNoClickThrough(true);
		w.setOpacity(isOpen() ? 0 : BUTTON_DIM);
		w.setOnMouseOverListener((JavaScriptCallback) e -> w.setOpacity(0));
		w.setOnMouseLeaveListener((JavaScriptCallback) e -> w.setOpacity(isOpen() ? 0 : BUTTON_DIM));
		w.setOnOpListener((JavaScriptCallback) e -> onClick.run());
		w.revalidate();
		return w;
	}

	/** Hides every widget this plugin added to the bank: the titles, their lines and the button. */
	private void removeWidgets()
	{
		hideFrom(headerText, 0);
		hideFrom(headerLine, 0);
		for (Widget w : buttonsInBank())
		{
			w.setHidden(true);
		}
		if (button != null)
		{
			button.setHidden(true);
			button = null;
		}
	}

	/** Keep / Sell anyway on items in the view. */
	void onMenuEntryAdded(MenuEntryAdded event, Actions actions)
	{
		if (event.getActionParam1() != InterfaceID.Bankmain.ITEMS || !"Examine".equals(event.getOption()) || !isOpen())
		{
			return;
		}
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		Widget item = container == null ? null : container.getChild(event.getActionParam0());
		if (item == null || item.getItemId() <= 0)
		{
			return;
		}
		int id = itemManager.canonicalize(item.getItemId());
		String target = event.getTarget();

		if (actions.isKept(id))
		{
			addEntry("Sell anyway", target, () -> actions.sellAnyway(id));
		}
		if (actions.isSellable(id))
		{
			addEntry("Keep", target, () -> actions.keepAll(id));
		}
	}

	private void addEntry(String option, String target, Runnable onClick)
	{
		client.getMenu().createMenuEntry(-1)
			.setOption(option)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> onClick.run());
	}

	/** What the menu entries do; the plugin answers. */
	interface Actions
	{
		boolean isSellable(int itemId);

		boolean isKept(int itemId);

		void keepAll(int itemId);

		void sellAnyway(int itemId);
	}
}

package com.loosechange;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import lombok.Value;

/**
 * The whole bank by what it's worth (Whole bank mode): every stack with a GE
 * price, before tax, whatever drops it. Coins and platinum tokens count.
 * Items with no price (most untradeables) are left out. Pure, so it runs in
 * unit tests.
 */
final class BankWorth
{
	@Value
	static class Row
	{
		int itemId;
		String name;
		int quantity;
		/** One item's GE price, before tax. */
		long price;

		long value()
		{
			return price * quantity;
		}
	}

	@Value
	static class Result
	{
		/** In the Sort By order. */
		List<Row> rows;
		long totalValue;

		static final Result EMPTY = new Result(Collections.emptyList(), 0);
	}

	private static final Comparator<Row> BY_VALUE = Comparator
		.comparingLong(Row::value).reversed()
		.thenComparing(Row::getName);
	private static final Comparator<Row> BY_PRICE = Comparator
		.comparingLong(Row::getPrice).reversed()
		.thenComparing(Row::getName);

	private BankWorth()
	{
	}

	/**
	 * @param bank  item id to quantity, already canonical (unnoted, no placeholders)
	 * @param items item facts by id; null when unknown
	 */
	static Result compute(Map<Integer, Integer> bank, IntFunction<SellList.Item> items, SortBy sort)
	{
		List<Row> rows = new ArrayList<>();
		long total = 0;
		for (Map.Entry<Integer, Integer> e : bank.entrySet())
		{
			int quantity = e.getValue();
			SellList.Item item = quantity > 0 ? items.apply(e.getKey()) : null;
			if (item == null || item.getGePrice() <= 0)
			{
				continue;
			}
			Row row = new Row(e.getKey(), item.getName(), quantity, item.getGePrice());
			rows.add(row);
			total += row.value();
		}
		rows.sort(sort == SortBy.ITEM_VALUE ? BY_PRICE : BY_VALUE);
		return new Result(Collections.unmodifiableList(rows), total);
	}
}

package com.loosechange;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * The bundled list of what bosses and raids drop (boss-drops.json, built by
 * a build script from the OSRS Wiki). Read once at startup.
 */
final class BossDrops
{
	static final String RESOURCE = "boss-drops.json";

	/** One boss (or raid) that drops an item. */
	@Value
	static class Source
	{
		String name;
		/** The drop rate as 1 in N; 0 when the wiki gives none. */
		int oneIn;
		/**
		 * A unique: in that boss's collection log and not dropped in stacks
		 * at 1 in 100 or more often. Listed only with Uniques unticked under Hide Drops.
		 */
		boolean rare;
	}

	/**
	 * A group of supplies a player can hide, in settings order. Gear and a
	 * boss's own loot (any collection log item) belong to none, except its
	 * teleport scrolls (Teleports) and seeds (Seeds). The names
	 * here are the keys in boss-drops.json, so never rename a constant.
	 */
	public enum Category
	{
		HERBS("Herbs"),
		SEEDS("Seeds"),
		POTIONS("Potions"),
		SECONDARIES("Herblore Secondaries"),
		RUNES("Runes"),
		AMMO("Ammo"),
		TIPS("Arrow and Bolt Tips"),
		FOOD("Food"),
		TELEPORTS("Teleports"),
		SKILLING("Skilling Materials");

		private final String label;

		Category(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Most common drop first, unknown rates last, then by name. */
	private static final Comparator<Source> MOST_COMMON_FIRST = Comparator
		.comparing((Source s) -> s.getOneIn() == 0)
		.thenComparingInt(Source::getOneIn)
		.thenComparing(Source::getName);

	private final Map<Integer, List<Source>> byItem;
	private final Map<Integer, Category> categories;
	private final int sourceCount;

	private BossDrops(Map<Integer, List<Source>> byItem, Map<Integer, Category> categories, int sourceCount)
	{
		this.byItem = byItem;
		this.categories = categories;
		this.sourceCount = sourceCount;
	}

	static BossDrops load(Gson gson) throws IOException
	{
		try (InputStream in = BossDrops.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException(RESOURCE + " is missing");
			}
			return parse(new InputStreamReader(in, StandardCharsets.UTF_8), gson);
		}
	}

	static BossDrops parse(Reader reader, Gson gson)
	{
		JsonObject root = gson.fromJson(reader, JsonObject.class);
		Map<Integer, List<Source>> byItem = new HashMap<>();
		JsonObject sources = root.getAsJsonObject("sources");
		for (Map.Entry<String, JsonElement> e : sources.entrySet())
		{
			JsonObject s = e.getValue().getAsJsonObject();
			add(byItem, e.getKey(), s.getAsJsonArray("n"), false);
			add(byItem, e.getKey(), s.getAsJsonArray("r"), true);
		}
		for (List<Source> list : byItem.values())
		{
			list.sort(MOST_COMMON_FIRST);
		}


		Map<Integer, Category> categories = new HashMap<>();
		JsonObject groups = root.getAsJsonObject("categories");
		if (groups != null)
		{
			for (Category c : Category.values())
			{
				JsonArray ids = groups.getAsJsonArray(c.name());
				if (ids != null)
				{
					ids.forEach(id -> categories.put(id.getAsInt(), c));
				}
			}
		}
		return new BossDrops(byItem, categories, sources.size());
	}

	private static void add(Map<Integer, List<Source>> byItem, String source, JsonArray drops, boolean rare)
	{
		if (drops == null)
		{
			return;
		}
		for (JsonElement d : drops)
		{
			JsonArray pair = d.getAsJsonArray();
			int itemId = pair.get(0).getAsInt();
			int oneIn = pair.get(1).getAsInt();
			byItem.computeIfAbsent(itemId, k -> new ArrayList<>(2)).add(new Source(source, oneIn, rare));
		}
	}

	/**
	 * The bosses that drop the item, most common drop first. Without rare
	 * drops, only bosses that drop it outside their collection log count.
	 * Empty when no boss counts.
	 */
	List<Source> sourcesOf(int itemId, boolean includeRare)
	{
		List<Source> all = byItem.get(itemId);
		if (all == null)
		{
			return Collections.emptyList();
		}
		if (includeRare)
		{
			return all;
		}
		List<Source> normal = new ArrayList<>(all.size());
		for (Source s : all)
		{
			if (!s.isRare())
			{
				normal.add(s);
			}
		}
		return normal;
	}

	/** Some boss drops it (rare drops included), so a setting could list it. */
	boolean has(int itemId)
	{
		return byItem.containsKey(itemId);
	}

	/** Every item some boss drops. */
	Set<Integer> itemIds()
	{
		return Collections.unmodifiableSet(byItem.keySet());
	}

	/** The supply group the item belongs to, or null for gear, boss loot and anything else. */
	Category categoryOf(int itemId)
	{
		return categories.get(itemId);
	}

	int itemCount()
	{
		return byItem.size();
	}

	int sourceCount()
	{
		return sourceCount;
	}
}

package com.loosechange;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.Toolkit;
import java.awt.font.FontRenderContext;
import java.awt.font.GlyphVector;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.util.Map;
import javax.swing.JLabel;

/**
 * A one-line label whose characters sit an even distance apart, for the big
 * total. The RuneScape bold font spaces its digits unevenly ("7" touches "4",
 * then a wide gap after the "4": 0 px and 3 px at its own 16 px, where the
 * rest are 2), and scaled up for the total the gap after a 4 reached 5 px.
 * Here each character's drawn edge is placed a set gap after
 * the one before, an eighth of the font size (2 px at 16). Text only, no
 * icon; left-aligned and centred up and down like a JLabel. Swing thread.
 */
final class EvenText extends JLabel
{
	/** How wide {@code text} draws in {@code font}, gaps evened out. */
	static float width(Font font, String text, FontRenderContext frc)
	{
		if (text == null || text.isEmpty())
		{
			return 0;
		}
		GlyphVector gv = spaced(font, text, frc);
		Rectangle2D first = gv.getGlyphVisualBounds(0).getBounds2D();
		Rectangle2D last = gv.getGlyphVisualBounds(text.length() - 1).getBounds2D();
		return (float) (last.getMaxX() - first.getMinX());
	}

	/** The text's glyphs moved so each starts a gap after the last one's drawn edge; the first's edge at x = 0. */
	private static GlyphVector spaced(Font font, String text, FontRenderContext frc)
	{
		GlyphVector gv = font.createGlyphVector(frc, text);
		float gap = font.getSize2D() / 8f;
		double edge = 0;
		for (int i = 0; i < gv.getNumGlyphs(); i++)
		{
			Point2D origin = gv.getGlyphPosition(i);
			Rectangle2D drawn = gv.getGlyphVisualBounds(i).getBounds2D();
			double bearing = drawn.getMinX() - origin.getX();
			// A blank glyph (a space) has no drawn edge: it keeps its own advance.
			double width = drawn.isEmpty() ? gv.getGlyphMetrics(i).getAdvance() : drawn.getWidth();
			gv.setGlyphPosition(i, new Point2D.Double(edge - bearing, origin.getY()));
			edge += width + gap;
		}
		return gv;
	}

	private FontRenderContext frc()
	{
		return getFontMetrics(getFont()).getFontRenderContext();
	}

	@Override
	public Dimension getPreferredSize()
	{
		Insets in = getInsets();
		FontMetrics fm = getFontMetrics(getFont());
		int w = (int) Math.ceil(width(getFont(), getText(), frc()));
		return new Dimension(w + in.left + in.right, fm.getHeight() + in.top + in.bottom);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return getPreferredSize();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		String text = getText();
		if (text == null || text.isEmpty())
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		// The same text smoothing Swing gives its labels.
		Map<?, ?> hints = (Map<?, ?>) Toolkit.getDefaultToolkit().getDesktopProperty("awt.font.desktophints");
		if (hints != null)
		{
			g2.addRenderingHints(hints);
		}
		g2.setFont(getFont());
		g2.setColor(getForeground());
		Insets in = getInsets();
		FontMetrics fm = g2.getFontMetrics();
		int inner = getHeight() - in.top - in.bottom;
		int baseline = in.top + (inner - fm.getHeight()) / 2 + fm.getAscent();
		g2.drawGlyphVector(spaced(getFont(), text, g2.getFontRenderContext()), in.left, baseline);
		g2.dispose();
	}
}

package com.loosechange;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * The Show in Bank tile: a box that lightens under the mouse, its icon
 * centred above a small label. The tooltip and the mouse handling are the
 * tile's alone: a Swing label with a tooltip of its own takes every mouse
 * event over it, so the click and the hover never reached the tile (the Show
 * in Bank that "did nothing"). Swing thread.
 */
final class FlatButton extends JPanel
{
	private final JLabel label = new JLabel("", SwingConstants.CENTER);

	FlatButton(Runnable onClick)
	{
		super(new BorderLayout());
		setBackground(PanelStyle.BOX);
		setBorder(new EmptyBorder(6, 4, 6, 4));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.setFont(PanelStyle.SMALL);
		label.setHorizontalTextPosition(SwingConstants.CENTER);
		label.setVerticalTextPosition(SwingConstants.BOTTOM);
		label.setIconTextGap(4);
		add(label, BorderLayout.CENTER);
		addMouseListener(new MouseAdapter()
		{
			// On press, as a click is lost if the mouse moves between press and release.
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setBackground(PanelStyle.BUTTON_HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setBackground(PanelStyle.BOX);
			}
		});
	}

	/** Sets what the tile says, its colour, icon and hover text. */
	void show(String text, Color color, @Nullable BufferedImage icon, String tip)
	{
		label.setText(text);
		label.setForeground(color);
		label.setIcon(icon == null ? null : new ImageIcon(icon));
		setToolTipText(tip);
	}
}

package com.loosechange;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.DynamicGridLayout;

/**
 * A titled box whose title folds it away: an arrow, the title in the box's colour and something at the title's
 * right (a total or a count). The fold is saved through {@link PanelFolds}.
 */
final class FoldingBox extends JPanel
{
	private static final Font ARROW_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);

	private final String id;
	private final PanelFolds folds;
	private final JLabel arrow = new JLabel();
	private final JPanel body = new JPanel(new DynamicGridLayout(0, 1, 0, 0));

	/**
	 * @param right the title bar's right side, or null
	 */
	FoldingBox(String id, String title, Color titleColor, JComponent right, PanelFolds folds)
	{
		this.id = id;
		this.folds = folds;
		setLayout(new BorderLayout(0, 6));
		setBackground(PanelStyle.BOX);
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel bar = new JPanel(new BorderLayout(5, 0));
		bar.setOpaque(false);
		bar.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		bar.setToolTipText("Click to fold or unfold");
		arrow.setFont(ARROW_FONT);
		arrow.setForeground(PanelStyle.LABEL);
		JLabel name = new JLabel(title);
		name.setFont(PanelStyle.TITLE_FONT);
		name.setForeground(titleColor);
		// Long names end in "..." rather than pushing the total out.
		name.setMinimumSize(new Dimension(0, 0));
		bar.add(arrow, BorderLayout.WEST);
		bar.add(name, BorderLayout.CENTER);
		if (right != null)
		{
			bar.add(right, BorderLayout.EAST);
		}
		MouseAdapter fold = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					folds.toggle(FoldingBox.this.id);
					updateFold();
				}
			}
		};
		bar.addMouseListener(fold);
		// A total with its own hover text takes the mouse over it, so it folds the box too.
		if (right != null)
		{
			right.addMouseListener(fold);
			right.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}

		body.setOpaque(false);
		add(bar, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
		updateFold();
	}

	/** Adds a line to the box's body. */
	void addContent(JComponent c)
	{
		body.add(c);
	}

	private void updateFold()
	{
		boolean open = folds.isOpen(id);
		arrow.setText(open ? "▼" : "▶");
		body.setVisible(open);
		revalidate();
		repaint();
	}
}

package com.loosechange;

import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * The Grand Exchange's 2% tax on sales: rounded down, at most 5m per item,
 * nothing on items under 50 gp, and a short list of exempt items
 * (oldschool.runescape.wiki/w/Grand_Exchange#Convenience_fee).
 */
final class GeTax
{
	static final int MIN_TAXED_PRICE = 50;
	static final long MAX_TAX = 5_000_000;

	/** Items the GE doesn't tax (the wiki's list, checked 26 Nov 2026). */
	static final Set<Integer> EXEMPT = Set.of(
		ItemID.OSRS_BOND,
		// Energy potion, every dose
		ItemID._4DOSE1ENERGY, ItemID._3DOSE1ENERGY, ItemID._2DOSE1ENERGY, ItemID._1DOSE1ENERGY,
		// Low level combat supplies
		ItemID.BRONZE_ARROW, ItemID.BRONZE_DART, ItemID.IRON_ARROW, ItemID.IRON_DART,
		ItemID.MINDRUNE, ItemID.STEEL_ARROW, ItemID.STEEL_DART,
		// Low level food
		ItemID.BASS, ItemID.BREAD, ItemID.CAKE, ItemID.COOKED_CHICKEN, ItemID.COOKED_MEAT,
		ItemID.HERRING, ItemID.LOBSTER, ItemID.MACKEREL, ItemID.MEAT_PIE, ItemID.PIKE,
		ItemID.SALMON, ItemID.SHRIMP, ItemID.TUNA,
		// Teleports
		ItemID.POH_TABLET_ARDOUGNETELEPORT, ItemID.POH_TABLET_CAMELOTTELEPORT,
		ItemID.POH_TABLET_FORTISTELEPORT, ItemID.POH_TABLET_FALADORTELEPORT,
		ItemID.NECKLACE_OF_MINIGAMES_8, ItemID.POH_TABLET_KOURENDTELEPORT,
		ItemID.POH_TABLET_LUMBRIDGETELEPORT, ItemID.RING_OF_DUELING_8,
		ItemID.POH_TABLET_TELEPORTTOHOUSE, ItemID.POH_TABLET_VARROCKTELEPORT,
		// Tools
		ItemID.CHISEL, ItemID.GARDENING_TROWEL, ItemID.GLASSBLOWINGPIPE, ItemID.HAMMER,
		ItemID.NEEDLE, ItemID.PESTLE_AND_MORTAR, ItemID.RAKE, ItemID.POH_SAW,
		ItemID.SECATEURS, ItemID.DIBBER, ItemID.SHEARS, ItemID.SPADE, ItemID.WATERING_CAN_0
	);

	private GeTax()
	{
	}

	/** Tax on selling one item at {@code price}. */
	static long tax(int itemId, long price)
	{
		if (price < MIN_TAXED_PRICE || EXEMPT.contains(itemId))
		{
			return 0;
		}
		return Math.min(price * 2 / 100, MAX_TAX);
	}

	/** What one item brings in after tax. */
	static long afterTax(int itemId, long price)
	{
		return price - tax(itemId, price);
	}
}

package com.loosechange;

import java.util.Locale;

/**
 * Gp amounts as RuneLite shows them: in full up to 10,000
 * (6,204), then 37.2K, 387K, 1.0M, 4.8M, 48.5M. Billions keep four figures
 * (2.147B, 21.47B, 214.7B), so an Entire Bank total never reads "2B" for
 * anything from 2 to 2.1 billion.
 */
final class Gp
{
	private Gp()
	{
	}

	static String format(long gp)
	{
		long abs = Math.abs(gp);
		if (abs < 10_000)
		{
			return exact(gp);
		}
		if (abs < 1_000_000)
		{
			return withSuffix(gp, 1_000, "K");
		}
		if (abs < 1_000_000_000)
		{
			return withSuffix(gp, 1_000_000, "M");
		}
		return billions(gp);
	}

	/** Four figures, cut rather than rounded, zeros kept: 2.000B, 2.147B, 21.47B, 214.7B, 2147B. */
	private static String billions(long gp)
	{
		long abs = Math.abs(gp);
		int decimals = abs < 10_000_000_000L ? 3 : abs < 100_000_000_000L ? 2 : abs < 1_000_000_000_000L ? 1 : 0;
		long scale = 1;
		for (int i = 0; i < decimals; i++)
		{
			scale *= 10;
		}
		long parts = abs / (1_000_000_000L / scale);
		String sign = gp < 0 ? "-" : "";
		if (decimals == 0)
		{
			return sign + parts + "B";
		}
		String fraction = String.format(Locale.ROOT, "%0" + decimals + "d", parts % scale);
		return sign + (parts / scale) + "." + fraction + "B";
	}

	/**
	 * One decimal below 100 of the unit (4.8M), none above (387K), cut rather
	 * than rounded. Always two figures at least: 1.0M, not "1M", which read as
	 * anything up to 1.9M; a ".0" from 10 up goes (37K).
	 */
	private static String withSuffix(long gp, long unit, String suffix)
	{
		long tenths = gp * 10 / unit;
		if (Math.abs(tenths) >= 1_000 || tenths % 10 == 0 && Math.abs(tenths) >= 100)
		{
			return (tenths / 10) + suffix;
		}
		return (tenths / 10) + "." + Math.abs(tenths % 10) + suffix;
	}

	/** A whole number with thousands separators: 1,580,000. */
	static String exact(long n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}
}

