package com.loosechange;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;

/**
 * Fits a pixel-art icon into a square tile once, for drawing every frame
 * after: its empty border trimmed so the art itself fills the tile, then
 * scaled only by whole numbers, as the game enlarges its own sprites. Growing
 * repeats each pixel 2, 3 or more times, so edges stay sharp; art too big
 * for the tile is shrunk to a half, a third and so on, averaging the pixels.
 * Between whole steps the icon is a little smaller than its tile rather than
 * smeared to fill it.
 */
final class IconFit
{
	private IconFit()
	{
	}

	/**
	 * The icon trimmed and scaled by a whole number to fit a {@code box}-pixel
	 * square; null while it has nothing drawn yet (an item image still loading).
	 */
	@Nullable
	static BufferedImage fit(BufferedImage icon, int box)
	{
		BufferedImage art = trim(icon);
		if (art == null || box <= 0)
		{
			return null;
		}
		int width = art.getWidth();
		int height = art.getHeight();
		if (width <= box && height <= box)
		{
			int times = Math.min(box / width, box / height);
			return times == 1 ? art : resize(art, width * times, height * times,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		}
		int part = 2;
		while (width / part > box || height / part > box)
		{
			part++;
		}
		return resize(art, Math.max(1, width / part), Math.max(1, height / part),
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
	}

	/** The smallest part of the image with anything drawn in it, or null if it's all clear. */
	@Nullable
	static BufferedImage trim(BufferedImage image)
	{
		int left = image.getWidth();
		int top = image.getHeight();
		int right = -1;
		int bottom = -1;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					left = Math.min(left, x);
					right = Math.max(right, x);
					top = Math.min(top, y);
					bottom = Math.max(bottom, y);
				}
			}
		}
		if (right < 0)
		{
			return null;
		}
		return image.getSubimage(left, top, right - left + 1, bottom - top + 1);
	}

	private static BufferedImage resize(BufferedImage image, int width, int height, Object interpolation)
	{
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = out.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation);
		graphics.drawImage(image, 0, 0, width, height, null);
		graphics.dispose();
		return out;
	}
}

package com.loosechange;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Constants;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The sidebar's item images, kept here and drawn a few at a time.
 *
 * <p>ItemManager keeps only 128 item images and draws each missing one on the
 * client thread, all in the same frame. Entire Bank has hundreds of rows, so
 * every rebuild of the panel (a tab, a grouping, a deposit) drew them all again
 * and froze the game for many seconds, holding up anything else waiting on the
 * client thread, such as Show in Bank. Here an image is drawn once per item and
 * stack size and kept, and the missing ones are drawn within a small time budget
 * each frame, top rows first.
 */
final class ItemImages
{
	/** More than a full bank's stacks, at 36 x 32 x 4 bytes each (about 7 MB). */
	private static final int KEEP = 1600;
	/** Client thread time spent drawing images each frame. */
	private static final long FRAME_BUDGET_NANOS = TimeUnit.MILLISECONDS.toNanos(3);

	private final ItemManager itemManager;
	private final ClientThread clientThread;

	private final Map<Long, AsyncBufferedImage> kept = new LinkedHashMap<Long, AsyncBufferedImage>(256, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, AsyncBufferedImage> eldest)
		{
			return size() > KEEP;
		}
	};
	private final ArrayDeque<Request> waiting = new ArrayDeque<>();
	private boolean draining;

	private static final class Request
	{
		final int itemId;
		final int quantity;
		final boolean stackable;
		final AsyncBufferedImage image;

		Request(int itemId, int quantity, boolean stackable, AsyncBufferedImage image)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.stackable = stackable;
			this.image = image;
		}
	}

	ItemImages(ItemManager itemManager, ClientThread clientThread)
	{
		this.itemManager = itemManager;
		this.clientThread = clientThread;
	}

	/** The item's image; blank until drawn, then filled in. Any thread. */
	synchronized AsyncBufferedImage get(int itemId, int quantity, boolean stackable)
	{
		long key = ((long) itemId << 33) | ((long) quantity << 1) | (stackable ? 1 : 0);
		AsyncBufferedImage image = kept.get(key);
		if (image == null)
		{
			image = new AsyncBufferedImage(clientThread, Constants.ITEM_SPRITE_WIDTH, Constants.ITEM_SPRITE_HEIGHT,
				BufferedImage.TYPE_INT_ARGB);
			kept.put(key, image);
			waiting.add(new Request(itemId, quantity, stackable, image));
			if (!draining)
			{
				draining = true;
				clientThread.invokeLater(this::draw);
			}
		}
		return image;
	}

	/** Client thread, each frame until none are waiting: draws images until the frame's budget is spent. */
	private boolean draw()
	{
		long end = System.nanoTime() + FRAME_BUDGET_NANOS;
		do
		{
			Request r;
			synchronized (this)
			{
				r = waiting.poll();
				if (r == null)
				{
					draining = false;
					return true;
				}
			}
			AsyncBufferedImage drawn = itemManager.getImage(r.itemId, r.quantity, r.stackable);
			// Drawn already on the client thread; later only if the game isn't ready yet.
			drawn.onLoaded(() ->
			{
				Graphics2D g = r.image.createGraphics();
				g.drawImage(drawn, 0, 0, null);
				g.dispose();
				r.image.loaded();
			});
		}
		while (System.nanoTime() < end);
		synchronized (this)
		{
			if (waiting.isEmpty())
			{
				draining = false;
				return true;
			}
		}
		return false;
	}

	/** Turning off: forget everything, so nothing more is drawn. */
	synchronized void clear()
	{
		kept.clear();
		waiting.clear();
	}
}

package com.loosechange;

import java.util.ArrayList;
import java.util.List;

/** The lines shown when hovering an item, in the bank view and the sidebar. */
final class ItemInfo
{
	/** Bosses named before "and N more". */
	static final int MAX_SOURCES = 4;

	private ItemInfo()
	{
	}

	static List<String> lines(SellList.Row row, boolean ironman, boolean showAlch)
	{
		List<String> lines = new ArrayList<>(5);
		lines.add(row.getName());
		lines.add("Sell " + Gp.exact(row.getSellQuantity()) + ": " + Gp.format(row.sellValue())
			+ (ironman ? " high alch" : " after tax")
			+ " (" + Gp.exact(row.getUnitValue()) + " each)");
		if (row.getKeptQuantity() > 0)
		{
			lines.add("Keeping " + Gp.exact(row.getKeptQuantity()));
		}
		if (showAlch && row.isAlchBetter())
		{
			lines.add("Worth more alched than sold");
		}
		lines.add("Dropped by " + sources(row.getSources()));
		return lines;
	}

	/**
	 * Whole bank mode: what the stack is worth before tax, and who drops it
	 * when it's also on the sellable list ({@code sellable} may be null).
	 */
	static List<String> worthLines(BankWorth.Row row, SellList.Row sellable)
	{
		List<String> lines = new ArrayList<>(3);
		lines.add(row.getName());
		lines.add(Gp.exact(row.getQuantity()) + " worth " + Gp.format(row.value())
			+ " (" + Gp.exact(row.getPrice()) + " each)");
		if (sellable != null)
		{
			lines.add("Dropped by " + sources(sellable.getSources()));
		}
		return lines;
	}

	/** "Vorkath, Zulrah and Duke Sucellus", or the first few "and 3 more". */
	static String sources(List<String> sources)
	{
		if (sources.isEmpty())
		{
			return "";
		}
		if (sources.size() == 1)
		{
			return sources.get(0);
		}
		if (sources.size() <= MAX_SOURCES)
		{
			return String.join(", ", sources.subList(0, sources.size() - 1)) + " and " + sources.get(sources.size() - 1);
		}
		return String.join(", ", sources.subList(0, MAX_SOURCES)) + " and " + (sources.size() - MAX_SOURCES) + " more";
	}
}

package com.loosechange;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * One item in a box: the game's item image with its stack number, the
 * name over a second line (the boss), and on the right the value in bold
 * over the price each. Without a second line, or a price each, that side is
 * one line centred beside the image. The Alch Tag sits before the value on its line.
 * Rows after the first get a hairline above. Kept rows look the same: the
 * Keep view is theirs alone. Swing thread.
 */
final class ItemRow extends JPanel
{
	static final int ICON_W = 36;
	static final int ICON_H = 32;

	/** What sits before the value: the Alch Tag icon, its word, or nothing. */
	static final class Alch
	{
		@Nullable
		final BufferedImage icon;
		final boolean word;

		Alch(@Nullable BufferedImage icon, boolean word)
		{
			this.icon = icon;
			this.word = word;
		}
	}

	/**
	 * @param second  the line under the name ("" for none)
	 * @param each    the price each, under the value ("" for none)
	 * @param alch    the Alch Tag before the value, or null
	 * @param first   the box's first row (no hairline above)
	 */
	ItemRow(AsyncBufferedImage image, String name, String second, String value, String each,
		@Nullable Alch alch, boolean first)
	{
		super(new BorderLayout(6, 0));
		setOpaque(false);
		setBackground(PanelStyle.ROW_HOVER);
		EmptyBorder pad = new EmptyBorder(3, 0, 3, 0);
		setBorder(first ? pad : new CompoundBorder(new MatteBorder(1, 0, 0, 0, PanelStyle.RULE), pad));

		JLabel icon = new JLabel();
		image.addTo(icon);
		icon.setPreferredSize(new Dimension(ICON_W, ICON_H));
		add(icon, BorderLayout.WEST);

		// Each side is two lines, or one centred up and down when its second is empty
		// (Entire Bank's single items, and the Show Drop Source setting off).
		JPanel text = new JPanel(new GridLayout(second.isEmpty() ? 1 : 2, 1, 0, 1));
		text.setOpaque(false);
		text.add(label(name, PanelStyle.REGULAR, Color.WHITE, SwingConstants.LEFT));
		if (!second.isEmpty())
		{
			text.add(label(second, PanelStyle.SMALL, PanelStyle.LABEL, SwingConstants.LEFT));
		}
		// Lets a long name end in "..." instead of pushing the value out.
		text.setMinimumSize(new Dimension(0, 0));
		text.setPreferredSize(new Dimension(0, ICON_H));
		add(text, BorderLayout.CENTER);

		JPanel right = new JPanel(new GridLayout(each.isEmpty() ? 1 : 2, 1, 0, 1));
		right.setOpaque(false);
		JPanel valueLine = new JPanel();
		valueLine.setLayout(new BoxLayout(valueLine, BoxLayout.X_AXIS));
		valueLine.setOpaque(false);
		valueLine.add(Box.createHorizontalGlue());
		if (alch != null)
		{
			JLabel tag = alch.word
				? label("Alch", PanelStyle.SMALL, ViewOverlay.ALCH_COLOR, SwingConstants.RIGHT)
				: new JLabel(alch.icon == null ? null : new ImageIcon(alch.icon));
			tag.setBorder(new EmptyBorder(0, 0, 0, 4));
			valueLine.add(tag);
		}
		valueLine.add(label(value, PanelStyle.BOLD, PanelStyle.VALUE, SwingConstants.RIGHT));
		right.add(valueLine);
		if (!each.isEmpty())
		{
			right.add(label(each, PanelStyle.SMALL, PanelStyle.QUIET, SwingConstants.RIGHT));
		}
		add(right, BorderLayout.EAST);

		setAlignmentX(LEFT_ALIGNMENT);
		inheritPopup(this);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				setOpaque(true);
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setOpaque(false);
				repaint();
			}
		});
	}

	private static void inheritPopup(JComponent parent)
	{
		for (Component c : parent.getComponents())
		{
			if (c instanceof JComponent)
			{
				((JComponent) c).setInheritsPopupMenu(true);
				inheritPopup((JComponent) c);
			}
		}
	}

	private static JLabel label(String text, Font font, Color color, int align)
	{
		JLabel l = new JLabel(text, align);
		l.setFont(font);
		l.setForeground(color);
		return l;
	}

	/** Rows are as tall as the item image and their padding, never stretched. */
	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.loosechange;

import lombok.Value;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;

/**
 * Keeps the Keep Items setting in step with the Keep lists. The setting
 * belongs to the RuneLite profile and the lists to accounts (RS profiles),
 * so the setting is a copy of one account's list: {@link Names#KEY_KEEP_ITEMS_ACCOUNT}
 * names that account, so an edit made while logged out still goes to the
 * list it shows, and the account is written before the text, so another
 * client on the same profile reading both applies the text to the right
 * account. This plugin's own writes are told from the player's edits by the
 * text last written ({@link #shown}). Each RuneLite profile holds its own
 * copy while the lists are shared, so a profile switch refreshes the copy
 * and never saves it. Text typed before any account has logged in goes to
 * the first one. Pure apart from {@link Store}, so it's unit tested.
 */
final class KeepItemsSync
{
	/** Where the setting and the lists are saved: RuneLite's config in the plugin. */
	interface Store
	{
		/** A setting of the RuneLite profile in use. */
		String get(String key);

		void set(String key, String value);

		/** An account's saved value. */
		String get(String account, String key);

		void set(String account, String key, String value);

		void unset(String account, String key);

		/** The RuneLite profile in use, by id. */
		long profileId();

		static Store of(ConfigManager config)
		{
			return new Store()
			{
				@Override
				public String get(String key)
				{
					return config.getConfiguration(Names.CONFIG_GROUP, key);
				}

				@Override
				public void set(String key, String value)
				{
					config.setConfiguration(Names.CONFIG_GROUP, key, value);
				}

				@Override
				public String get(String account, String key)
				{
					return config.getConfiguration(Names.CONFIG_GROUP, account, key);
				}

				@Override
				public void set(String account, String key, String value)
				{
					config.setConfiguration(Names.CONFIG_GROUP, account, key, value);
				}

				@Override
				public void unset(String account, String key)
				{
					config.unsetConfiguration(Names.CONFIG_GROUP, account, key);
				}

				@Override
				public long profileId()
				{
					ConfigProfile profile = config.getProfile();
					return profile == null ? -1 : profile.getId();
				}
			};
		}
	}

	/** An account's list as saved, to decode; {@code save} when it must be saved again (taken over, or in the old id form). */
	@Value
	static class Loaded
	{
		String saved;
		boolean save;
	}

	private final Store store;
	/** The Keep Items text this plugin last wrote or took in, so its own writes aren't read as edits. */
	private volatile String shown;
	/**
	 * The RuneLite profile whose Keep Items setting this is in step with. A
	 * switch reports the next profile's text as a change before
	 * ProfileChanged comes, which must never be taken as an edit.
	 */
	private volatile long profile;

	KeepItemsSync(Store store)
	{
		this.store = store;
		this.profile = store.profileId();
	}

	/** At startup and on ProfileChanged: from here on a Keep Items change is the player's again. */
	void profileChanged()
	{
		profile = store.profileId();
	}

	/**
	 * Whether a Keep Items change can be the player's edit: false while a
	 * RuneLite profile switch is reporting the next profile's copy, which may
	 * be empty or old and, taken as an edit, would replace the account's list.
	 * Ask on the thread the change came on, before {@link #profileChanged}.
	 */
	boolean mayBeEdit()
	{
		return store.profileId() == profile;
	}

	/**
	 * The account's saved list. With none saved and the setting standing for
	 * no account so far, the first account takes what was typed into it.
	 */
	Loaded load(String account)
	{
		String saved = account == null ? null : store.get(account, Names.KEY_KEEP);
		boolean save = false;
		if (account != null && saved == null && store.get(Names.KEY_KEEP_ITEMS_ACCOUNT) == null)
		{
			saved = KeepList.normalize(store.get(Names.KEY_KEEP_ITEMS));
			save = !saved.isEmpty();
		}
		// Lists saved before names were item ids; save them as names.
		save |= KeepList.isOldForm(saved);
		return new Loaded(saved, save);
	}

	/** Saves an account's list ({@link KeepList#encode}); an empty one is removed. */
	void save(String account, String encoded)
	{
		if (account == null)
		{
			return;
		}
		if (encoded == null || encoded.isEmpty())
		{
			store.unset(account, Names.KEY_KEEP);
		}
		else
		{
			store.set(account, Names.KEY_KEEP, encoded);
		}
	}

	/** Puts the account's list ({@link KeepList#text}) in the setting. Logged out (null), the setting keeps the last account's. */
	void show(String account, String text)
	{
		if (account == null)
		{
			return;
		}
		if (!account.equals(store.get(Names.KEY_KEEP_ITEMS_ACCOUNT)))
		{
			store.set(Names.KEY_KEEP_ITEMS_ACCOUNT, account);
		}
		write(text);
	}

	/**
	 * After a RuneLite profile switch: the new profile's setting shows the
	 * list it stands for, not the copy it held from its last use.
	 *
	 * @param account the logged-in account, or null
	 * @param text    that account's list ({@link KeepList#text}), when logged in
	 */
	void showAfterProfileSwitch(String account, String text)
	{
		if (account != null)
		{
			show(account, text);
			return;
		}
		// Logged out: the setting stands for the account it names.
		String named = store.get(Names.KEY_KEEP_ITEMS_ACCOUNT);
		if (named == null)
		{
			return;
		}
		String saved = store.get(named, Names.KEY_KEEP);
		if (KeepList.isOldForm(saved))
		{
			// Turned into names when that account next logs in.
			return;
		}
		write(KeepList.normalize(saved));
	}

	/**
	 * The setting changed to {@code value}: unless it's this plugin's own
	 * write, the player edited it. Saves it under the account the setting
	 * stands for (the one it names, else the logged-in one).
	 *
	 * @param loaded the logged-in account, or null
	 * @return the new list text when it's the logged-in account's, to show
	 *         now; null when nothing changed or another account's list did
	 */
	String edited(String value, String loaded)
	{
		String text = value == null ? "" : value;
		if (text.equals(shown))
		{
			return null;
		}
		shown = text;
		String account = store.get(Names.KEY_KEEP_ITEMS_ACCOUNT);
		if (account == null)
		{
			account = loaded;
		}
		if (account == null)
		{
			// No account seen yet: the first one to log in takes it (load).
			return null;
		}
		String saved = KeepList.normalize(text);
		save(account, saved);
		return account.equals(loaded) ? saved : null;
	}

	private void write(String text)
	{
		shown = text;
		store.set(Names.KEY_KEEP_ITEMS, text);
	}
}

package com.loosechange;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import java.util.regex.Pattern;

/**
 * Items the player keeps instead of selling, per account: a list of item
 * names, as typed in the Keep Items setting or added by Keep on the bank
 * menu. A kept item keeps its whole stack.
 * <p>
 * A name stands for the item's family (every potion dose, charged and
 * uncharged forms), so keeping Saradomin brew(4) also keeps brew(3). A line
 * with a {@code *} is a wildcard, as in Ground Items: {@code *} stands for
 * any run of characters, so {@code Rune*} keeps every item whose name starts
 * with "Rune". Lines that match no item stay on the list, so the player can
 * see and fix them.
 */
final class KeepList
{
	/** The id form saved before names: "565:all,11237:1000". */
	private static final Pattern OLD_FORM = Pattern.compile("\\s*\\d+:[^,]*(,\\s*\\d+:[^,]*)*");

	private final IntUnaryOperator family;
	/** Every item name the list can match, lower-cased, to an item id. */
	private Map<String, Integer> index = Collections.emptyMap();
	/** Lower-cased line to the line as written, in list order; one entry per line. */
	private final Map<String, String> lines = new LinkedHashMap<>();
	/** Lower-cased line to the families it stands for (none when it matches nothing). */
	private final Map<String, Set<Integer>> families = new HashMap<>();
	private final Set<Integer> kept = new HashSet<>();

	/**
	 * @param family maps an item to the id its family is stored under
	 *               (in the plugin, ItemVariationMapping::map)
	 */
	KeepList(IntUnaryOperator family)
	{
		this.family = family;
	}

	/**
	 * Sets the names lines are matched against, and matches the list again.
	 *
	 * @param index every item name the list can match, lower-cased, to an
	 *              item id ({@link #index(Iterable, IntFunction)})
	 */
	void setIndex(Map<String, Integer> index)
	{
		this.index = index;
		matchAll();
	}

	private void matchAll()
	{
		families.clear();
		kept.clear();
		for (String key : lines.keySet())
		{
			match(key);
		}
	}

	private void match(String key)
	{
		Set<Integer> found = new HashSet<>();
		if (isWildcard(key))
		{
			Pattern p = wildcard(key);
			for (Map.Entry<String, Integer> e : index.entrySet())
			{
				if (p.matcher(e.getKey()).matches())
				{
					found.add(family.applyAsInt(e.getValue()));
				}
			}
		}
		else
		{
			Integer id = index.get(key);
			if (id != null)
			{
				found.add(family.applyAsInt(id));
			}
		}
		families.put(key, found);
		kept.addAll(found);
	}

	boolean has(int itemId)
	{
		return kept.contains(family.applyAsInt(itemId));
	}

	/** How many of a stack of {@code quantity} are kept: all of it, or none. */
	int keptOf(int itemId, int quantity)
	{
		return has(itemId) ? quantity : 0;
	}

	/** Keep: adds the item under {@code name} (its name in game), unless it's kept already. */
	void keep(int itemId, String name)
	{
		String clean = name.trim();
		if (has(itemId) || clean.isEmpty() || isWildcard(clean))
		{
			return;
		}
		String key = key(clean);
		lines.remove(key);
		lines.put(key, clean);
		int f = family.applyAsInt(itemId);
		families.put(key, new HashSet<>(Collections.singleton(f)));
		kept.add(f);
	}

	/**
	 * Keep from a search: adds a wildcard line ("*rune*"), which keeps every
	 * drop it fits, now and later. Nothing if the line (any case) is there.
	 */
	void keepWildcard(String line)
	{
		String clean = line.trim();
		String key = key(clean);
		if (!isWildcard(clean) || lines.containsKey(key))
		{
			return;
		}
		lines.put(key, clean);
		match(key);
	}

	/**
	 * Sell anyway: removes every name line for the item. Wildcard lines stay,
	 * so an item a wildcard also covers stays kept ({@link #wildcardsFor}).
	 */
	void sellAnyway(int itemId)
	{
		int f = family.applyAsInt(itemId);
		lines.keySet().removeIf(key -> !isWildcard(key) && families.get(key).contains(f));
		families.keySet().retainAll(lines.keySet());
		kept.clear();
		for (Set<Integer> s : families.values())
		{
			kept.addAll(s);
		}
	}

	/** The wildcard lines that keep the item, as written. */
	List<String> wildcardsFor(int itemId)
	{
		int f = family.applyAsInt(itemId);
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, String> e : lines.entrySet())
		{
			if (isWildcard(e.getKey()) && families.get(e.getKey()).contains(f))
			{
				out.add(e.getValue());
			}
		}
		return out;
	}

	boolean isEmpty()
	{
		return lines.isEmpty();
	}

	/**
	 * The lines that match no item, as written: misspelled names, and
	 * wildcards nothing on the drop list fits (the index is every drop, not
	 * just the bank, so those never match).
	 */
	List<String> unknown()
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, String> e : lines.entrySet())
		{
			if (families.get(e.getKey()).isEmpty())
			{
				out.add(e.getValue());
			}
		}
		return out;
	}

	/** The list as the Keep Items setting shows it: one line per name or wildcard. */
	String text()
	{
		return String.join("\n", lines.values());
	}

	/** Replaces the list with {@code text}: names one per line (commas also split). */
	void setText(String text)
	{
		lines.clear();
		for (String line : parse(text))
		{
			lines.put(key(line), line);
		}
		matchAll();
	}

	/** Saved form: the same as {@link #text()}. */
	String encode()
	{
		return text();
	}

	/**
	 * Replaces the list with a saved one. Reads the id form saved before
	 * names too ("565:all,11237:1000"), naming each item with {@code nameOf};
	 * a Keep X amount there becomes keeping the whole stack.
	 */
	void decode(String saved, IntFunction<String> nameOf)
	{
		if (isOldForm(saved))
		{
			List<String> converted = new ArrayList<>();
			for (String entry : saved.split(","))
			{
				String id = entry.substring(0, entry.indexOf(':')).trim();
				String name = nameOf.apply(Integer.parseInt(id));
				if (name != null && !name.trim().isEmpty() && !name.equalsIgnoreCase("null"))
				{
					converted.add(name);
				}
			}
			setText(String.join("\n", converted));
		}
		else
		{
			setText(saved);
		}
	}

	static boolean isOldForm(String saved)
	{
		return saved != null && !saved.trim().isEmpty() && OLD_FORM.matcher(saved).matches();
	}

	static boolean isWildcard(String line)
	{
		return line.indexOf('*') >= 0;
	}

	/** A wildcard line as a pattern over lower-cased names: {@code *} is any run of characters, the rest literal. */
	static Pattern wildcard(String line)
	{
		StringBuilder regex = new StringBuilder();
		String[] parts = key(line).split("\\*", -1);
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				regex.append(".*");
			}
			if (!parts[i].isEmpty())
			{
				regex.append(Pattern.quote(parts[i]));
			}
		}
		return Pattern.compile(regex.toString(), Pattern.DOTALL);
	}

	/** {@code text} as the list would save it: trimmed, blank lines and repeats (any case) dropped. */
	static String normalize(String text)
	{
		return String.join("\n", parse(text));
	}

	/** The lines in {@code text}: one per line or comma, trimmed, first spelling of each kept. */
	static List<String> parse(String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		Map<String, String> out = new LinkedHashMap<>();
		for (String part : text.split("[\\r\\n,]+"))
		{
			String name = part.trim();
			if (!name.isEmpty())
			{
				out.putIfAbsent(key(name), name);
			}
		}
		return new ArrayList<>(out.values());
	}

	/**
	 * Every item name to an item id, lower-cased, for {@link #setIndex}. The
	 * first id given a name keeps it, so pass the main items before their
	 * other forms.
	 */
	static Map<String, Integer> index(Iterable<Integer> ids, IntFunction<String> nameOf)
	{
		Map<String, Integer> out = new HashMap<>();
		for (int id : ids)
		{
			String name = nameOf.apply(id);
			if (name != null && !name.trim().isEmpty() && !name.equalsIgnoreCase("null"))
			{
				out.putIfAbsent(key(name.trim()), id);
			}
		}
		return out;
	}

	static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}
}

