 * Type tabs (Sellable, not in the kept list); then the list. Ungrouped and
 * kept, the list is one plain box (the strip is its title); grouped, a
 * folding box a boss or type. Entire Bank lists every priced stack in one
 * folding "Entire Bank" box. Before the bank is seen, or with nothing
 * listed, a message card takes the list's place. Right-click a row to Keep, Sell Anyway or open the
 * wiki. All methods run on the Swing thread.
 */
class LooseChangePanel extends PluginPanel
{
	/** The empty values before the bank is seen. */
	private static final String NONE = "-";
	/** How long typing in the search box pauses before the list filters. */
	private static final int SEARCH_PAUSE_MS = 120;

	/** Everything the panel shows, worked out on the client thread. */
	@Value
	@Builder
	static class State
	{
		@Builder.Default
		SellList.Result result = SellList.Result.EMPTY;
		@Builder.Default
		BankWorth.Result worth = BankWorth.Result.EMPTY;
		boolean bankKnown;
		@Builder.Default
		ListMode mode = ListMode.SELLABLE;
		@Builder.Default
		GroupBy groupBy = GroupBy.NONE;
		@Builder.Default
		SharedItems shared = SharedItems.BIGGEST_GROUP;
		@Builder.Default
		AlchMark alchMark = AlchMark.OFF;
		/** Show Drop Source: each row names its boss under the item (off: one line, centred). */
		@Builder.Default
		boolean bossLine = true;
	}

	/** What the panel's buttons and menus do; the plugin answers. */
	interface Listener
	{
		/** Show the view, close it, or (bank closed) open it with the bank or stop waiting. */
		void showInBank();

		void setListMode(ListMode mode);

		void setGroupBy(GroupBy by);

		void keepAll(int itemId);

		/** Adds a wildcard line ("*rune*") to Keep Items, from the search. */
		void keepWildcard(String line);

		/** The sidebar search changed ({@link Search#normalize normalized}; "" when cleared). */
		void searchChanged(String query);

		void sellAnyway(int itemId);

		void openWiki(int itemId);
	}

	/** Where the panel's images come from: the game, through ItemManager and SpriteManager. */
	interface Images
	{
		/** An item's image, as {@link ItemManager#getImage(int, int, boolean)} draws it. */
		AsyncBufferedImage item(int itemId, int quantity, boolean stackable);

		/** A game sprite, handed over once loaded (any thread). */
		void sprite(int spriteId, Consumer<BufferedImage> loaded);

		static Images of(ItemImages items, SpriteManager spriteManager)
		{
			return new Images()
			{
				@Override
				public AsyncBufferedImage item(int itemId, int quantity, boolean stackable)
				{
					return items.get(itemId, quantity, stackable);
				}

				@Override
				public void sprite(int spriteId, Consumer<BufferedImage> loaded)
				{
					spriteManager.getSpriteAsync(spriteId, 0, loaded::accept);
				}
			};
		}
	}

	private final Images images;
	private final Listener listener;
	private final PanelFolds folds;

	private final JLabel coins = new JLabel();
	/** The total, its characters evenly spaced (the font leaves a wide gap after a 4). */
	private final EvenText total = new EvenText();
	/**
	 * The total's tile; its hover has the exact figures. Beside the coin pile
	 * there's about 60 px: a total too wide for the total font drops to the
	 * tile font (20 pt).
	 */
	private final JPanel hero = new JPanel(new BorderLayout(8, 0))
	{
		@Override
		public void doLayout()
		{
			super.doLayout();
			float need = EvenText.width(PanelStyle.TOTAL_FONT, total.getText(),
				total.getFontMetrics(PanelStyle.TOTAL_FONT).getFontRenderContext());
			total.setFont(need <= total.getWidth() ? PanelStyle.TOTAL_FONT : PanelStyle.TILE_FONT);
		}
	};
	/** The total tile and Show in Bank, side by side. */
	private final JPanel tiles;
	private final FlatButton showButton;
	/** Sell / Keep: the list's title and its switch. */
	private final JPanel keptStrip = new JPanel(new GridLayout(1, 2));
	private final Half sellHalf = new Half(false, "Sell", "Back to the items to sell");
	private final Half keptHalf = new Half(true, "Keep", "Show the items you keep, to Sell Anyway any of them");
	private final JLabel[] modeTabs = new JLabel[ListMode.values().length];
	private final JLabel[] tabs = new JLabel[GroupBy.values().length];
	private final JComponent groupStrip;
	/** The search box, RuneLite's own field. */
	private final IconTextField search = new IconTextField();
	/** The search as typed, trimmed and lower-cased; "" for none. Kept across views, not saved. */
	private String query = "";
	/**
	 * Filters once typing pauses: one rebuild for a burst of keys, and none of
	 * the whole list between the remove and insert of typing over a selection.
	 */
	private final Timer searchPause = new Timer(SEARCH_PAUSE_MS, e -> searchChanged());
	/** The boss each row is listed under, for the search ({@link Search#listedBoss}). */
	private Function<SellList.Row, String> bossOf = SellList.Row::topSource;
	/** The drop list's rows by item id, for sale or kept: Entire Bank's boss lines. */
	private Map<Integer, SellList.Row> dropRows = Collections.emptyMap();
	/** Keep "*rune*": adds the search to Keep Items as a wildcard line. */
	private final JLabel keepSearchArg = new JLabel();
	private final JPanel keepSearch;
	private final JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 8));

	@Nullable
	private BufferedImage coinImage;
	@Nullable
	private BufferedImage smallCoinImage;
	@Nullable
	private BufferedImage bankIcon;

	private State state = State.builder().build();
	private SellList.Result result = SellList.Result.EMPTY;
	private GroupBy groupBy = GroupBy.NONE;
	private boolean bankKnown;
	private AlchMark alchMark = AlchMark.OFF;
	private BufferedImage alchIcon;
	private boolean pending;
	private boolean viewOpen;
	/** The list shows the kept items instead of the ones to sell; the Keep half of the strip. Not saved. */
	private boolean keptView;
	private boolean deferWhileHidden;
	/** Something changed while the panel was hidden; rebuilt when it opens. */
	private boolean stale;

	LooseChangePanel(Images images, PanelFolds folds, Listener listener)
	{
		this.images = images;
		this.listener = listener;
		this.folds = folds;

		setBorder(new EmptyBorder(10, 8, 10, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new DynamicGridLayout(0, 1, 0, 8));

		add(tabStrip(modeTabs, new String[]{"Sellable", ListMode.WHOLE_BANK.toString()}, new String[]{
			"Boss drops you could sell, after GE tax",
			"Every stack in your bank by its GE value, before tax",
		}, i -> listener.setListMode(ListMode.values()[i])));
		showButton = new FlatButton(listener::showInBank);
		tiles = new JPanel(new TileLayout());
		tiles.setOpaque(false);
		tiles.add(header());
		tiles.add(showButton);
		add(tiles);
		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 30));
		search.setBackground(PanelStyle.BOX);
		search.setHoverBackgroundColor(PanelStyle.BUTTON_HOVER);
		searchPause.setRepeats(false);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				searchPause.restart();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				searchPause.restart();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				searchPause.restart();
			}
		});
		keepSearch = keepSearchButton();
		keptStrip.setBackground(PanelStyle.BOX);
		keptStrip.add(sellHalf);
		keptStrip.add(keptHalf);
		groupStrip = tabStrip(tabs, new String[]{"Default", "By Boss", "By Type"}, new String[]{
			"Every item in one list",
			"A box for each boss; an item several bosses drop goes under one (Shared Drops setting)",
			"A box for each type of item (herbs, runes and so on) and one for boss loot",
		}, i -> listener.setGroupBy(GroupBy.values()[i]));
		add(groupStrip);
		list.setOpaque(false);
		add(list);

		// The coin pile, as the game draws a big stack, without its number.
		AsyncBufferedImage pile = images.item(ItemID.COINS, 10_000, false);
		pile.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			coinImage = IconFit.trim(pile);
			rebuild();
		}));
		AsyncBufferedImage smallPile = images.item(ItemID.COINS, 250, false);
		smallPile.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			smallCoinImage = IconFit.trim(smallPile);
			rebuild();
		}));
		// The game's bank map icon.
		images.sprite(SpriteID.Mapfunction._5, sprite -> SwingUtilities.invokeLater(() ->
		{
			bankIcon = IconFit.trim(sprite);
			rebuild();
		}));
		rebuild();
	}

	void update(State state, BufferedImage alchIcon)
	{
		this.state = state;
		this.result = state.getResult();
		this.groupBy = state.getGroupBy();
		this.bossOf = Search.listedBoss(result, groupBy, state.getShared());
		this.dropRows = Search.byId(result);
		this.bankKnown = state.isBankKnown();
		this.alchMark = state.getAlchMark();
		this.alchIcon = alchIcon;
		rebuild();
	}

	/**
	 * In the client: while the sidebar shows another plugin, changes (every
	 * deposit, say) only mark the list stale, and it's built when the panel
	 * opens. Not for PanelPreview, which draws a panel that's never shown.
	 */
	void deferWhileHidden()
	{
		deferWhileHidden = true;
	}

	@Override
	public void onActivate()
	{
		super.onActivate();
		// Opening: build now, showing or not quite yet.
		if (stale)
		{
			build();
		}
	}

	private boolean whole()
	{
		return state.getMode() == ListMode.WHOLE_BANK;
	}

	/** "Show in Bank" was pressed with the bank closed, or that wait ended. */
	void setPending(boolean waiting)
	{
		pending = waiting;
		updateButton();
	}

	/** Whether the bank view is showing in the open bank. */
	void setViewOpen(boolean open)
	{
		viewOpen = open;
		updateButton();
	}

	/** Shows the kept items, as the strip's Keep half does (for PanelPreview). */
	void setKeptView(boolean on)
	{
		keptView = on;
		rebuild();
	}

	/** After a RuneLite profile switch: that profile's folded boxes. */
	void reloadFolds()
	{
		folds.reload();
		rebuild();
	}

	// ---- Building blocks ----

	/**
	 * The total with the coin pile, alone in its
	 * tile. What it counts (after tax, at high alch, before tax) and the stack
	 * and slot counts are in its hover.
	 */
	private JComponent header()
	{
		hero.setBackground(PanelStyle.BOX);
		hero.setBorder(new EmptyBorder(10, 8, 10, 8));
		coins.setPreferredSize(new Dimension(32, 32));
		hero.add(coins, BorderLayout.WEST);
		total.setFont(PanelStyle.TOTAL_FONT);
		hero.add(total, BorderLayout.CENTER);
		return hero;
	}

	/** Show in Bank says what pressing it does now. */
	private void updateButton()
	{
		String text;
		String tip;
		Color color = Color.WHITE;
		BufferedImage icon = bankIcon;
		if (viewOpen)
		{
			text = "Close Bank View";
			tip = "Go back to your normal bank";
		}
		else if (pending)
		{
			text = "Opens with Bank";
			tip = "Shows the view next time you open your bank. Click to cancel";
			color = PanelStyle.LABEL;
			icon = icon == null ? null : faded(icon, 0.5f);
		}
		else
		{
			text = "Show in Bank";
			tip = "Show these items as a view of your bank, high to low";
		}
		showButton.show(text, color, icon, tip);
	}

	/**
	 * A row of tabs, edge to edge.Sellable / Entire Bank fills the one
	 * in use with a lighter grey; Default / By Boss / By Type keeps the accent
	 * underline, the panel's only accent line.
	 */
	private JComponent tabStrip(JLabel[] into, String[] names, String[] tips, IntConsumer onClick)
	{
		JPanel strip = new JPanel(new GridLayout(1, names.length));
		strip.setBackground(PanelStyle.BOX);
		for (int i = 0; i < names.length; i++)
		{
			int index = i;
			JLabel tab = new JLabel(names[i], SwingConstants.CENTER);
			// Opaque, so the selected fill paints the whole cell.
			tab.setOpaque(true);
			tab.setBackground(PanelStyle.BOX);
			tab.setFont(PanelStyle.REGULAR);
			tab.setToolTipText(tips[i]);
			tab.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			tab.addMouseListener(new MouseAdapter()
			{
				// On press, left button only, as every other control here.
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e))
					{
						onClick.accept(index);
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					tab.setForeground(Color.WHITE);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					styleTabs();
				}
			});
			into[i] = tab;
			strip.add(tab);
		}
		return strip;
	}

	private void styleTabs()
	{
		for (ListMode m : ListMode.values())
		{
			filledTab(modeTabs[m.ordinal()], m == state.getMode());
		}
		for (GroupBy by : GroupBy.values())
		{
			underlinedTab(tabs[by.ordinal()], by == groupBy);
		}
	}

	/** Sellable / Entire Bank: the one in use filled, white; same padding either way, so nothing shifts. */
	private static void filledTab(JLabel tab, boolean on)
	{
		tab.setForeground(on ? Color.WHITE : PanelStyle.LABEL);
		tab.setBackground(on ? PanelStyle.SELECTED : PanelStyle.BOX);
		tab.setBorder(new EmptyBorder(6, 0, 6, 0));
	}

	/** Default / By Boss / By Type: the accent underline on the one in use, the same height either way. */
	private static void underlinedTab(JLabel tab, boolean on)
	{
		tab.setForeground(on ? Color.WHITE : PanelStyle.LABEL);
		tab.setBorder(on
			? BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 0, 2, 0, PanelStyle.ACCENT), new EmptyBorder(6, 0, 4, 0))
			: new EmptyBorder(6, 0, 6, 0));
	}

	/**
	 * Half of the Sell / Keep strip: the word in the title font, then the
	 * count. The one in use is filled a lighter grey, Sell in green and
	 * Keep in white; the other is quiet. Pressing a half shows its list. The
	 * mouse handling and tooltip are the half's alone, as in {@link FlatButton}.
	 */
	private final class Half extends JPanel
	{
		private final boolean kept;
		private final JLabel word;
		private final JLabel count = new JLabel();

		Half(boolean kept, String name, String tip)
		{
			super(new FlowLayout(FlowLayout.CENTER, 6, 0));
			this.kept = kept;
			((FlowLayout) getLayout()).setAlignOnBaseline(true);
			// Opaque, so the selected fill covers the whole half; the halves meet with no gap.
			setOpaque(true);
			setBorder(new EmptyBorder(7, 0, 7, 0));
			setToolTipText(tip);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			word = new JLabel(name);
			word.setFont(PanelStyle.TITLE_FONT);
			count.setFont(PanelStyle.REGULAR);
			count.setForeground(PanelStyle.LABEL);
			add(word);
			add(count);
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e) && keptView != Half.this.kept)
					{
						keptView = Half.this.kept;
						rebuild();
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					if (!on())
					{
						word.setForeground(Color.WHITE);
					}
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					style(Half.this.count.getText());
				}
			});
		}

		private boolean on()
		{
			return keptView == kept;
		}

		void style(String n)
		{
			count.setText(n);
			word.setForeground(!on() ? PanelStyle.QUIET : kept ? Color.WHITE : PanelStyle.ACCENT);
			setBackground(on() ? PanelStyle.SELECTED : PanelStyle.BOX);
		}
	}

	// ---- Filling it in ----

	private void rebuild()
	{
		if (deferWhileHidden && !isShowing())
		{
			stale = true;
			return;
		}
		build();
	}

	private void build()
	{
		stale = false;
		updateHeader();
		styleTabs();
		// Grouping is for the sellable drops; the whole bank is one list. Taken
		// out rather than hidden, as the panel's grid keeps a hidden row's gap.
		// The kept items aren't grouped either; Entire Bank has no Keep.
		boolean showKept = !whole() && bankKnown;
		if (!showKept)
		{
			keptView = false;
		}
		// The search box: under the tiles in both views, once there's a bank to search.
		if (bankKnown != (search.getParent() == this))
		{
			if (bankKnown)
			{
				add(search, getComponentZOrder(tiles) + 1);
			}
			else
			{
				remove(search);
			}
		}
		if (showKept != (keptStrip.getParent() == this))
		{
			if (showKept)
			{
				add(keptStrip, getComponentZOrder(bankKnown ? search : tiles) + 1);
			}
			else
			{
				remove(keptStrip);
			}
		}
		// Searching, both halves count their matches, so a kept match shows from Sell.
		sellHalf.style(Gp.exact(matching(result.getSellable()).size()));
		keptHalf.style(Gp.exact(matching(result.getKept()).size()));
		// Nor is there anything to group before the bank is seen (Getting Started).
		boolean showGroups = !whole() && !keptView && bankKnown;
		if (showGroups != (groupStrip.getParent() == this))
		{
			if (showGroups)
			{
				add(groupStrip, getComponentZOrder(list));
			}
			else
			{
				remove(groupStrip);
			}
		}
		// Keep "*rune*": on the sell list, while the search as a Keep line would keep something there.
		String line = keepLine();
		boolean showKeepSearch = showGroups && line != null;
		if (showKeepSearch)
		{
			keepSearchArg.setText("\"" + line + "\"");
		}
		if (showKeepSearch != (keepSearch.getParent() == this))
		{
			if (showKeepSearch)
			{
				add(keepSearch, getComponentZOrder(list));
			}
			else
			{
				remove(keepSearch);
			}
		}

		updateButton();

		clear(list);
		if (whole())
		{
			rebuildWhole();
		}
		else
		{
			rebuildSellable();
		}
		revalidate();
		repaint();
	}

	/** Entire Bank: every stack with a GE price, in one box, by its value before tax. */
	private void rebuildWhole()
	{
		BankWorth.Result worth = state.getWorth();
		if (!bankKnown)
		{
			// No Keep in Entire Bank, so its third step is the wiki click.
			list.add(gettingStarted("Open your bank once.", "Every stack in your bank lists here by its GE value, most valuable first.",
				"Middle-click any for its wiki page."));
			return;
		}
		if (worth.getRows().isEmpty())
		{
			list.add(card(smallCoinImage, "Nothing Priced", "Nothing in your bank has a GE price."));
			return;
		}
		List<BankWorth.Row> rows = Search.filter(query, worth, result).getRows();
		if (rows.isEmpty())
		{
			list.add(noMatches());
			return;
		}
		// The fold id stays "whole" (saved), whatever the title says.
		FoldingBox box = new FoldingBox("whole", ListMode.WHOLE_BANK.toString(), PanelStyle.ACCENT, count(rows.size()), folds);
		boolean first = true;
		for (BankWorth.Row row : rows)
		{
			box.addContent(worthRow(row, first));
			first = false;
		}
		list.add(box);
	}

	private void rebuildSellable()
	{
		if (!bankKnown)
		{
			list.add(gettingStarted("Open your bank once.", "Boss drops you could sell list here, most valuable first.",
				"Right-click any you want to keep."));
		}
		else if (keptView)
		{
			rebuildKept();
		}
		else if (result.getSellable().isEmpty())
		{
			list.add(card(smallCoinImage, "Nothing to Sell",
				"No boss drops in your bank are listed. Hide Drops and Hide Stacks Under in the settings decide which are."));
		}
		else if (matching(result.getSellable()).isEmpty())
		{
			list.add(noMatches());
		}
		else if (groupBy == GroupBy.NONE)
		{
			// The Sell half of the strip is its title. (Its old fold, "sell", may still be saved; it's no longer read.)
			JPanel box = plainBox();
			boolean first = true;
			for (SellList.Row row : matching(result.getSellable()))
			{
				box.add(sellRow(row, false, first));
				first = false;
			}
			list.add(box);
		}
		else
		{
			String kind = groupBy == GroupBy.BOSS ? "boss:" : "type:";
			for (SellList.Group g : result.groups(groupBy, state.getShared()))
			{
				// Searching, a group shows its matches and their worth; one with none goes.
				List<SellList.Row> rows = matching(g.getRows());
				if (rows.isEmpty())
				{
					continue;
				}
				long worth = searching() ? rows.stream().mapToLong(SellList.Row::sellValue).sum() : g.getValue();
				JLabel value = new JLabel(Gp.format(worth));
				value.setFont(PanelStyle.BOLD);
				value.setForeground(PanelStyle.VALUE);
				value.setToolTipText(Gp.exact(worth) + " gp");
				FoldingBox box = new FoldingBox(kind + g.getTitle(), PanelStyle.groupTitle(g.getTitle()), PanelStyle.ACCENT, value, folds);
				// By boss the title already says who drops it.
				boolean first = true;
				for (SellList.Row row : rows)
				{
					box.addContent(sellRow(row, groupBy == GroupBy.BOSS, first));
					first = false;
				}
				list.add(box);
			}
		}
	}

	/** The strip's Kept list: every kept stack in one plain box, each with Sell Anyway on its menu. */
	private void rebuildKept()
	{
		if (result.getKept().isEmpty())
		{
			list.add(card(smallCoinImage, "Nothing Kept",
				"Right-click an item and pick Keep, or add names to Keep Items in the settings."));
			return;
		}
		if (matching(result.getKept()).isEmpty())
		{
			list.add(noMatches());
			return;
		}
		// The Keep half of the strip is its title. (Its old fold, "keptView", may still be saved; it's no longer read.)
		JPanel kept = plainBox();
		boolean first = true;
		for (SellList.Row row : matching(result.getKept()))
		{
			kept.add(keptRow(row, first));
			first = false;
		}
		list.add(kept);
	}

	// ---- Search ----

	private void searchChanged()
	{
		String q = Search.normalize(search.getText());
		if (!q.equals(query))
		{
			query = q;
			rebuild();
			// With Search Bank View on, the plugin filters the open bank view too.
			listener.searchChanged(q);
		}
	}

	/** Types into the search box, as a player would, and filters at once (for PanelPreview). */
	void setSearch(String text)
	{
		search.setText(text);
		searchPause.stop();
		searchChanged();
	}

	private boolean searching()
	{
		return !query.isEmpty();
	}

	/** The rows the search matches ({@link Search}), in their order; all of them when not searching. */
	private List<SellList.Row> matching(List<SellList.Row> rows)
	{
		return Search.rows(query, rows, bossOf);
	}

	/**
	 * The search as a Keep Items line: as typed if it has a {@code *},
	 * else {@code *text*}. Null when not searching, or when the line would
	 * keep nothing on the sell list, so the button never does nothing (a
	 * search that found its items by boss name only).
	 */
	@Nullable
	private String keepLine()
	{
		if (!searching())
		{
			return null;
		}
		String line = KeepList.isWildcard(query) ? query : "*" + query + "*";
		if (line.replace("*", "").trim().isEmpty())
		{
			// "*" would keep every drop at a click, and Sell Anyway never takes a wildcard off.
			return null;
		}
		Pattern p = KeepList.wildcard(line);
		for (SellList.Row row : result.getSellable())
		{
			if (p.matcher(KeepList.key(row.getName())).matches())
			{
				return line;
			}
		}
		return null;
	}

	/** The Keep "*rune*" button: the line in green, as it will read in Keep Items. */
	private JPanel keepSearchButton()
	{
		JPanel b = new JPanel();
		b.setLayout(new BoxLayout(b, BoxLayout.X_AXIS));
		b.setBackground(PanelStyle.BOX);
		b.setBorder(new EmptyBorder(6, 8, 6, 8));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		b.setToolTipText("Add this line to Keep Items: it keeps every drop it fits, now and later");
		JLabel word = new JLabel("Keep ");
		word.setFont(PanelStyle.REGULAR);
		word.setForeground(Color.WHITE);
		keepSearchArg.setFont(PanelStyle.REGULAR);
		keepSearchArg.setForeground(PanelStyle.ACCENT);
		// A long search ends in "..." rather than running out of the button.
		keepSearchArg.setMinimumSize(new Dimension(0, 0));
		b.add(Box.createHorizontalGlue());
		b.add(word);
		b.add(keepSearchArg);
		b.add(Box.createHorizontalGlue());
		b.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				String line = keepLine();
				if (SwingUtilities.isLeftMouseButton(e) && line != null)
				{
					listener.keepWildcard(line);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				b.setBackground(PanelStyle.BUTTON_HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				b.setBackground(PanelStyle.BOX);
			}
		});
		return b;
	}

	/**
	 * Nothing in this list matches. When the other half of the Sell / Keep
	 * strip has matches (searching "rune" with every Rune item kept), the
	 * card says so and a click shows them, rather than a bare "no matches".
	 */
	private JComponent noMatches()
	{
		if (!whole())
		{
			int other = matching(keptView ? result.getSellable() : result.getKept()).size();
			if (other > 0)
			{
				String n = other == 1 ? "Your 1 match is" : "All " + Gp.exact(other) + " matches are";
				JComponent c = card(smallCoinImage, keptView ? "None Kept" : "All Kept",
					n + (keptView ? " for sale." : " on Keep.") + " Click to see " + (other == 1 ? "it." : "them."));
				c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				c.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						if (SwingUtilities.isLeftMouseButton(e))
						{
							keptView = !keptView;
							rebuild();
						}
					}
				});
				return c;
			}
		}
		// One short line, so it reads as centred; the box's cross clears the search.
		return card(smallCoinImage, "No Matches", "Try another name.");
	}

	private void updateHeader()
	{
		boolean listed = bankKnown;
		long value;
		String tip;
		if (whole())
		{
			BankWorth.Result worth = state.getWorth();
			value = worth.getTotalValue();
			int n = worth.getRows().size();
			long sellable = result.getTotalValue();
			tip = Gp.exact(value) + " gp at GE prices, before tax<br>"
				+ Gp.exact(n) + (n == 1 ? " stack" : " stacks") + " with a GE price<br>"
				+ Gp.exact(sellable) + " gp of it is boss drops you could sell";
		}
		else
		{
			value = result.getTotalValue();
			int n = result.getSellable().size();
			int freed = result.getSlotsFreed();
			tip = Gp.exact(value) + " gp " + (result.isIronman() ? "at high alch" : "after GE tax") + "<br>"
				+ Gp.exact(n) + (n == 1 ? " stack" : " stacks") + " to sell, freeing "
				+ Gp.exact(freed) + (freed == 1 ? " bank slot" : " bank slots");
		}
		total.setText(listed ? Gp.format(value) : NONE);
		total.setForeground(listed && value > 0 ? PanelStyle.VALUE : PanelStyle.QUIET);
		String html = listed ? "<html>" + tip + "</html>" : null;
		hero.setToolTipText(html);
		total.setToolTipText(html);
		coins.setToolTipText(html);

		BufferedImage pile = coinImage;
		coins.setIcon(pile == null ? null : new ImageIcon(listed && value > 0 ? pile : faded(pile, 0.35f)));
	}

	private JComponent sellRow(SellList.Row row, boolean byBoss, boolean first)
	{
		String second = byBoss ? "" : source(row);
		String each = row.getSellQuantity() > 1 ? Gp.format(row.getUnitValue()) + " Each" : "";
		ItemRow.Alch alch = null;
		if (alchMark != AlchMark.OFF && row.isAlchBetter() && !result.isIronman())
		{
			alch = new ItemRow.Alch(alchIcon, alchMark == AlchMark.LABEL);
		}
		ItemRow p = new ItemRow(images.item(row.getItemId(), row.getSellQuantity(), row.getSellQuantity() > 1),
			row.getName(), second, Gp.format(row.sellValue()), each, alch, first);
		p.setToolTipText(RowTooltip.forSale(row, result.isIronman(), alchMark != AlchMark.OFF));

		JPopupMenu menu = new JPopupMenu();
		menu.add(item("Keep", () -> listener.keepAll(row.getItemId())));
		menu.add(item("Wiki", () -> listener.openWiki(row.getItemId())));
		withMenus(p, menu, row.getItemId());
		return p;
	}

	/** A kept stack, drawn as a row to sell is: the Keep view sets it apart. */
	private JComponent keptRow(SellList.Row row, boolean first)
	{
		int quantity = row.getKeptQuantity();
		String each = quantity > 1 ? Gp.format(row.getUnitValue()) + " Each" : "";
		ItemRow p = new ItemRow(images.item(row.getItemId(), quantity, quantity > 1),
			row.getName(), source(row), Gp.format(row.getUnitValue() * quantity), each, null, first);
		p.setToolTipText(RowTooltip.kept(row));

		JPopupMenu menu = new JPopupMenu();
		menu.add(item("Sell Anyway", () -> listener.sellAnyway(row.getItemId())));
		menu.add(item("Wiki", () -> listener.openWiki(row.getItemId())));
		withMenus(p, menu, row.getItemId());
		return p;
	}

	/** Entire Bank: a stack, its GE value before tax over the price each; the boss when it's on the drop list (for sale or kept). */
	private JComponent worthRow(BankWorth.Row row, boolean first)
	{
		SellList.Row sellable = dropRows.get(row.getItemId());
		// Coins and the like are worth 1 each: nothing to say.
		String each = row.getQuantity() > 1 && row.getPrice() > 1 ? Gp.format(row.getPrice()) + " Each" : "";
		ItemRow p = new ItemRow(images.item(row.getItemId(), row.getQuantity(), row.getQuantity() > 1),
			row.getName(), sellable == null ? "" : source(sellable), Gp.format(row.value()), each, null, first);
		p.setToolTipText(RowTooltip.worth(row, sellable));

		JPopupMenu menu = new JPopupMenu();
		menu.add(item("Wiki", () -> listener.openWiki(row.getItemId())));
		withMenus(p, menu, row.getItemId());
		return p;
	}

	/** A row's right-click menu, and a middle click that opens the item's wiki page straight away. */
	private void withMenus(JComponent row, JPopupMenu menu, int itemId)
	{
		row.setComponentPopupMenu(menu);
		row.addMouseListener(new MouseAdapter()
		{
			// On press, as a click is lost if the mouse moves between press and release.
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isMiddleMouseButton(e))
				{
					listener.openWiki(itemId);
				}
			}
		});
	}

	/** The boss line under a row's name, or "" with Show Drop Source off. The hover always names the bosses. */
	private String source(SellList.Row row)
	{
		return state.isBossLine() ? row.topSource() : "";
	}
}

