@Slf4j
@PluginDescriptor(
	name = Names.DISPLAY,
	description = "Bank full of boss loot? See what to sell, most gp first. Shown in your bank and the sidebar, with your whole bank's worth from anywhere; ironmen see high alch values",
	tags = {"bank", "sell", "ge", "grand exchange", "loot", "drops", "boss", "raid", "money", "gp", "value", "keep", "liquidate", "clean up", "bank space", "cox", "tob", "toa", "tfa", "ironman", "alch", "high alch"}
)
@PluginDependency(BankTagsPlugin.class)
public class LooseChangePlugin extends Plugin implements LooseChangePanel.Listener, BankView.Actions
{
	private static final String WIKI_ITEM = "https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ConfigManager configManager;
	@Inject
	private LooseChangeConfig config;
	@Inject
	private ItemManager itemManager;
	@Inject
	private SpriteManager spriteManager;
	@Inject
	private ChatMessageManager chatMessageManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private Gson gson;
	@Inject
	private BankView bankView;
	@Inject
	private ViewOverlay viewOverlay;

	private BossDrops drops;
	private final KeepList keep = new KeepList(ItemVariationMapping::map);
	private LooseChangePanel panel;
	private ItemImages itemImages;
	private NavigationButton navButton;

	/** Between startUp and shutDown: callbacks queued before shutDown (a menu click, a deferred open) do nothing after it. */
	private volatile boolean running;

	// Client thread state (bank and bankChanged are also read at client shutdown)
	/**
	 * The RS profile whose Keep list and bank copy are loaded. Saves go under
	 * this key only: when the account changes RuneLite has already moved to
	 * the next key, and the last account's unsaved bank still belongs to it.
	 */
	private volatile String loadedKey;
	/** The last bank seen (canonical id to the whole stack, every item); null until one is seen for this account. */
	private volatile Map<Integer, Integer> bank;
	private volatile boolean bankChanged;
	/** The Keep Items setting kept in step with the Keep lists; made at startup. */
	private volatile KeepItemsSync keepSync;
	private boolean ironman;
	private volatile SellList.Result result = SellList.Result.EMPTY;
	/** Every priced stack in the bank (Whole bank mode). */
	private volatile BankWorth.Result worth = BankWorth.Result.EMPTY;
	/** {@link #result}'s items for sale by id: the bank menu asks on every hover. */
	private volatile Map<Integer, SellList.Row> sellableById = Collections.emptyMap();
	/** The sidebar's search, normalized; the bank view uses it with Search Bank View on. Client thread. */
	private String search = "";
	/** "Show in bank" was pressed with the bank closed. */
	private boolean openWithBank;
	/** The bank interface just opened and hasn't been drawn yet. */
	private boolean firstBuild;

	@Provides
	LooseChangeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LooseChangeConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		migrateByBoss();
		drops = BossDrops.load(gson);
		log.debug("{} items from {} bosses and raids", drops.itemCount(), drops.sourceCount());

		itemImages = new ItemImages(itemManager, clientThread);
		panel = new LooseChangePanel(LooseChangePanel.Images.of(itemImages, spriteManager), PanelFolds.of(configManager), this);
		panel.deferWhileHidden();
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "sidebar_icon.png");
		navButton = NavigationButton.builder()
			.tooltip(Names.DISPLAY)
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(viewOverlay);
		keepSync = new KeepItemsSync(KeepItemsSync.Store.of(configManager));
		running = true;

		clientThread.invoke(() ->
		{
			// The sidebar's search box starts empty, so the bank view's filter does too.
			search = "";
			bankView.startUp();
			clientThread.invoke((BooleanSupplier) this::loadItemNames);
			// By the RS profile, not the game state: turned on during a loading
			// screen or a hop, the account is known but not "logged in", and no
			// profile change follows to load it.
			loadAccount();
			// Turned on mid-session: the bank the client holds is newer than the saved copy.
			ItemContainer held = client.getItemContainer(InventoryID.BANK);
			if (loadedKey != null && held != null)
			{
				readBank(held);
			}
			// Turned on with the bank open: its button now, not at the bank's next redraw.
			if (bankView.isBankOpen())
			{
				bankView.setButtonShown(config.bankButton(), this::toggleBankView);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(viewOverlay);
		clientThread.invoke(() ->
		{
			saveBank();
			bankView.shutDown();
			bank = null;
			loadedKey = null;
			openWithBank = false;
			result = SellList.Result.EMPTY;
			sellableById = Collections.emptyMap();
		});
		panel = null;
		itemImages.clear();
	}

	/** The old List / By boss toggle becomes Group By, so By boss stays By boss. */
	private void migrateByBoss()
	{
		String old = configManager.getConfiguration(Names.CONFIG_GROUP, Names.KEY_BY_BOSS_OLD);
		if (old == null)
		{
			return;
		}
		if (Boolean.parseBoolean(old) && configManager.getConfiguration(Names.CONFIG_GROUP, Names.KEY_GROUP_BY) == null)
		{
			configManager.setConfiguration(Names.CONFIG_GROUP, Names.KEY_GROUP_BY, GroupBy.BOSS);
		}
		configManager.unsetConfiguration(Names.CONFIG_GROUP, Names.KEY_BY_BOSS_OLD);
	}

	// ---- Account state ----

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invoke(() ->
		{
			if (!running)
			{
				return;
			}
			// The last account's bank first, under its own key (logging out or
			// disconnecting with the bank open never closes it).
			saveBank();
			loadAccount();
		});
	}

	/**
	 * A RuneLite profile switch: the new profile needs this plugin's Bank Tag
	 * Layouts marker too, and its Keep Items setting the list shown.
	 */
	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// From here on a Keep Items change is the player's again (onConfigChanged).
		keepSync.profileChanged();
		clientThread.invoke(() ->
		{
			if (running)
			{
				bankView.startUp();
				keepSync.showAfterProfileSwitch(loadedKey, keep.text());
			}
		});
		// The new profile's folded sidebar boxes.
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.reloadFolds();
			}
		});
	}

	/** The client is closing: plugins aren't shut down, and RuneLite writes settings to disk after this. */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		saveBank();
	}

	/** Loads the current RS profile's Keep list and bank copy; with no profile (logged out), empties them. */
	private void loadAccount()
	{
		String key = configManager.getRSProfileKey();
		loadedKey = key;
		loadKeep(key);
		// The whole bank, not just drop list items: Whole bank mode lists every stack.
		bank = key == null ? null : BankCopy.decode(configManager.getConfiguration(Names.CONFIG_GROUP, key, Names.KEY_BANK));
		bankChanged = false;
		if (openWithBank)
		{
			// "Show in bank" was for the last account's bank.
			openWithBank = false;
			setPending(false);
		}
		readIronman();
		refresh();
	}

	/** Loads the account's Keep list and shows it in the Keep Items setting. */
	private void loadKeep(String key)
	{
		KeepItemsSync.Loaded loaded = keepSync.load(key);
		keep.decode(loaded.getSaved(), id -> itemManager.getItemComposition(id).getName());
		if (loaded.isSave())
		{
			saveKeep();
		}
		keepSync.show(key, keep.text());
	}

	private void saveBank()
	{
		String key = loadedKey;
		Map<Integer, Integer> saved = bank;
		if (bankChanged && saved != null && key != null)
		{
			bankChanged = false;
			configManager.setConfiguration(Names.CONFIG_GROUP, key, Names.KEY_BANK, BankCopy.encode(saved));
		}
	}

	private void saveKeep()
	{
		keepSync.save(loadedKey, keep.isEmpty() ? "" : keep.encode());
	}

	private void readIronman()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			// 0 is a normal account; every ironman kind (group ones too) can't sell on the GE.
			ironman = client.getVarbitValue(VarbitID.IRONMAN) != 0;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			saveBank();
			// Logging out with the bank open never closes it (onWidgetClosed).
			forgetViewUnlessRemembered();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.IRONMAN)
		{
			boolean was = ironman;
			readIronman();
			if (was != ironman)
			{
				refresh();
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!Names.CONFIG_GROUP.equals(event.getGroup()) || event.getProfile() != null)
		{
			return;
		}
		if (Names.KEY_KEEP_ITEMS.equals(event.getKey()))
		{
			if (!keepSync.mayBeEdit())
			{
				// A RuneLite profile switch, not an edit; onProfileChanged brings the copy up to date.
				return;
			}
			String value = event.getNewValue();
			clientThread.invoke(() ->
			{
				if (running)
				{
					keepItemsEdited(value);
				}
			});
		}
		else if (Names.KEY_REMEMBER_BANK_VIEW.equals(event.getKey()))
		{
			// Unticked with the bank closed on the view: the next bank opens normally.
			clientThread.invoke(this::forgetViewUnlessRemembered);
		}
		// The sidebar's folded boxes are saved here too, and change nothing listed.
		else if (!Names.KEY_KEEP_ITEMS_ACCOUNT.equals(event.getKey()) && !PanelFolds.KEY.equals(event.getKey()))
		{
			boolean sidebarOnly = Names.KEY_BOSS_LINE.equals(event.getKey());
			clientThread.invoke(() ->
			{
				refresh();
				// Settings change what's listed: lay the open view out again.
				if (bankView.isOpen() && !sidebarOnly)
				{
					openView();
				}
				if (bankView.isBankOpen())
				{
					bankView.setButtonShown(config.bankButton(), this::toggleBankView);
				}
			});
		}
	}

	// ---- Bank ----

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			readBank(event.getItemContainer());
		}
	}

	/** Takes in the bank's contents (its drop list items); works the list out again if they changed. */
	private void readBank(ItemContainer container)
	{
		Item[] items = container.getItems();
		int[] ids = new int[items.length];
		int[] quantities = new int[items.length];
		for (int i = 0; i < items.length; i++)
		{
			ids[i] = items[i].getId();
			quantities[i] = items[i].getQuantity();
		}
		Map<Integer, Integer> now = BankCopy.canonical(ids, quantities, itemManager::canonicalize, this::isPlaceholder);
		if (!now.equals(bank))
		{
			bank = now;
			bankChanged = true;
			refresh();
		}
	}

	/** A bank placeholder: the faded slot left when a stack is withdrawn. */
	private boolean isPlaceholder(int itemId)
	{
		return itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankView.onBankLoaded();
			firstBuild = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			saveBank();
			showViewOpen(false);
			forgetViewUnlessRemembered();
		}
	}

	/**
	 * Remember Bank View off: the next bank opens on the normal bank, though
	 * Bank Tags (its Remember last tag tab) would reopen the view it closed on.
	 */
	private void forgetViewUnlessRemembered()
	{
		if (running && !config.rememberBankView())
		{
			bankView.forgetLastTab();
		}
	}

	/** The sidebar's button says Close Bank View while the view shows in the open bank. */
	private void showViewOpen(boolean open)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setViewOpen(open);
			}
		});
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
		{
			return;
		}
		bankView.onBankBuilt(viewTitle(config.listMode(), result, worth), config.hidePlaceholders(), config.bankButton(),
			this::toggleBankView);
		fitTitleLater();
		// Opening or closing the view rebuilds the bank, so this sees both,
		// including Bank Tags reopening it by itself.
		showViewOpen(bankView.isOpen());
		// Bank Tags can reopen the view itself when the bank opens ("remember
		// tab"); lay it out from the current bank then, not the last visit's.
		boolean stale = firstBuild && bankView.isOpen();
		firstBuild = false;
		if (stale && !openWithBank && !config.rememberBankView())
		{
			// Reopened by Bank Tags all the same (a close this plugin missed): the normal bank.
			clientThread.invokeLater(() -> bankView.close());
		}
		else if (openWithBank || stale)
		{
			openWithBank = false;
			setPending(false);
			// Not from inside the bank's own script: opening a tag rebuilds the bank.
			clientThread.invokeLater(() -> openView());
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		bankView.onMenuEntryAdded(event, this);
	}

	/**
	 * Keeps the view's title clear of the bank button, once every plugin has
	 * written its part of the title (RuneLite's Bank plugin adds the value of
	 * what's shown after this plugin's title is set).
	 */
	private void fitTitleLater()
	{
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				bankView.fitTitle();
			}
		});
	}

	/** Opens the bank view, or lays it out again. Needs the bank open. */
	private void openView()
	{
		// Not once turned off: it would open the unregistered tag and save its layout again.
		// Not with the bank closed either (Bank Tags keeps the tag active then): there
		// are no item slots to lay out, and the next bank open lays it out anyway.
		if (running && bankView.isBankOpen())
		{
			int slots = bankView.itemSlots();
			// Search Bank View: the sidebar's search cuts the view to its matches (the title's totals stay whole).
			String query = config.searchBankView() ? search : "";
			GroupBy by = config.groupBy();
			SharedItems shared = config.sharedItems();
			bankView.open(config.listMode() == ListMode.WHOLE_BANK
				? BankLayout.whole(Search.filter(query, worth, result), slots)
				: BankLayout.build(Search.filter(query, result, Search.listedBoss(result, by, shared)), by, shared, slots));
		}
	}

	private void toggleBankView()
	{
		if (!running)
		{
			return;
		}
		if (bankView.isOpen())
		{
			bankView.close();
		}
		else
		{
			openView();
		}
	}

	// ---- Working out the list ----

	/** Works the list out again and shows it. Client thread. */
	private void refresh()
	{
		if (drops == null)
		{
			return;
		}
		long started = System.nanoTime();
		SellList.Settings settings = SellList.Settings.builder()
			.includeRare(!config.hideRare())
			.hidden(hiddenGroups())
			.hideUnder(Math.max(0, config.hideUnder()))
			.hideOver(Math.max(0, config.hideOver()))
			.ironman(ironman)
			.sort(config.sortBy())
			.build();
		SellList.Result r = bank == null
			? SellList.Result.EMPTY
			: SellList.compute(bank, drops, this::itemFacts, keep, settings);
		BankWorth.Result w = bank == null
			? BankWorth.Result.EMPTY
			: BankWorth.compute(bank, this::itemFacts, config.sortBy());
		result = r;
		worth = w;

		Map<Integer, SellList.Row> rows = new HashMap<>();
		for (SellList.Row row : r.getSellable())
		{
			rows.put(row.getItemId(), row);
		}
		sellableById = rows;
		Map<Integer, BankWorth.Row> worthRows = new HashMap<>();
		for (BankWorth.Row row : w.getRows())
		{
			worthRows.put(row.getItemId(), row);
		}
		ListMode mode = config.listMode();
		AlchMark alchMark = config.alchMark();
		viewOverlay.update(rows, mode == ListMode.WHOLE_BANK ? worthRows : null, alchMark, r.isIronman());
		// Live: the open view's title follows every change.
		bankView.updateTitle(viewTitle(mode, r, w));
		// The sidebar button's words follow the view's real state, however it opened.
		showViewOpen(bankView.isBankOpen() && bankView.isOpen());

		LooseChangePanel.State state = LooseChangePanel.State.builder()
			.result(r)
			.worth(w)
			.bankKnown(bank != null)
			.mode(mode)
			.groupBy(config.groupBy())
			.shared(config.sharedItems())
			.alchMark(alchMark)
			.bossLine(config.bossLine())
			.build();
		log.debug("Worked out {} to sell and {} bank stacks in {} ms", r.getSellable().size(), w.getRows().size(),
			(System.nanoTime() - started) / 1_000_000);
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				long built = System.nanoTime();
				panel.update(state, viewOverlay.getAlchIcon());
				log.debug("Sidebar rebuilt in {} ms", (System.nanoTime() - built) / 1_000_000);
			}
		});
	}

	/** The supply groups ticked under Hide Drops. */
	private Set<BossDrops.Category> hiddenGroups()
	{
		Set<BossDrops.Category> hidden = EnumSet.noneOf(BossDrops.Category.class);
		addIf(hidden, config.hidePotions(), BossDrops.Category.POTIONS);
		addIf(hidden, config.hideRunes(), BossDrops.Category.RUNES);
		addIf(hidden, config.hideFood(), BossDrops.Category.FOOD);
		addIf(hidden, config.hideTeleports(), BossDrops.Category.TELEPORTS);
		addIf(hidden, config.hideHerbs(), BossDrops.Category.HERBS);
		addIf(hidden, config.hideSeeds(), BossDrops.Category.SEEDS);
		addIf(hidden, config.hideSecondaries(), BossDrops.Category.SECONDARIES);
		addIf(hidden, config.hideAmmo(), BossDrops.Category.AMMO);
		addIf(hidden, config.hideTips(), BossDrops.Category.TIPS);
		addIf(hidden, config.hideSkilling(), BossDrops.Category.SKILLING);
		return hidden;
	}

	private static void addIf(Set<BossDrops.Category> set, boolean on, BossDrops.Category c)
	{
		if (on)
		{
			set.add(c);
		}
	}

	private SellList.Item itemFacts(int itemId)
	{
		ItemComposition c = itemManager.getItemComposition(itemId);
		return new SellList.Item(c.getName(), c.isTradeable(), itemManager.getItemPrice(itemId), c.getHaPrice());
	}

	// ---- Keep ----

	@Override
	public boolean isSellable(int itemId)
	{
		// Keep belongs to the sellable list; the whole bank view has no Keep section.
		return config.listMode() == ListMode.SELLABLE && sellableById.containsKey(itemId);
	}

	@Override
	public boolean isKept(int itemId)
	{
		return config.listMode() == ListMode.SELLABLE && keep.has(itemId);
	}

	@Override
	public void keepAll(int itemId)
	{
		clientThread.invoke(() ->
		{
			if (canKeep(loadedKey))
			{
				keep.keep(itemId, itemManager.getItemComposition(itemId).getName());
				keepChanged();
			}
		});
	}

	@Override
	public void searchChanged(String query)
	{
		clientThread.invoke(() ->
		{
			search = query;
			if (running && config.searchBankView() && bankView.isOpen())
			{
				openView();
				bankView.updateTitle(viewTitle(config.listMode(), result, worth));
			}
		});
	}

	/** The bank view's title, naming the search while Search Bank View filters by it. */
	private String viewTitle(ListMode mode, SellList.Result r, BankWorth.Result w)
	{
		return BankView.title(mode, r, w, config.searchBankView() ? search : "");
	}

	@Override
	public void keepWildcard(String line)
	{
		clientThread.invoke(() ->
		{
			if (canKeep(loadedKey))
			{
				keep.keepWildcard(line);
				keepChanged();
			}
		});
	}

	@Override
	public void sellAnyway(int itemId)
	{
		clientThread.invoke(() ->
		{
			if (canKeep(loadedKey))
			{
				keep.sellAnyway(itemId);
				keepChanged();
				// A wildcard line still keeps it: say which, rather than seem to do nothing.
				List<String> wildcards = keep.wildcardsFor(itemId);
				if (!wildcards.isEmpty())
				{
					chat(itemManager.getItemComposition(itemId).getName() + " is still kept by "
						+ quoted(wildcards) + " in Keep Items. Edit that line in settings to sell it.");
				}
			}
		});
	}

	/** Keep changes save under the loaded account; none without one, or once turned off. */
	private boolean canKeep(String account)
	{
		return running && account != null && account.equals(loadedKey);
	}

	private void keepChanged()
	{
		saveKeep();
		keepSync.show(loadedKey, keep.text());
		keepShown();
	}

	/** Shows the Keep list as it is now: in the list, and in an open bank view. */
	private void keepShown()
	{
		refresh();
		if (bankView.isOpen())
		{
			openView();
		}
	}

	// ---- Keep Items setting ----
	// A copy of one account's Keep list, kept in step by KeepItemsSync.

	/** Builds the name lookup once item names can be read. Client thread; false means try again next tick. */
	private boolean loadItemNames()
	{
		if (!running)
		{
			return true;
		}
		if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
		{
			return false;
		}
		// Drop list items first, so their names win over other forms'.
		Set<Integer> ids = new LinkedHashSet<>(drops.itemIds());
		for (int id : drops.itemIds())
		{
			ids.addAll(ItemVariationMapping.getVariations(ItemVariationMapping.map(id)));
		}
		Map<String, Integer> index = KeepList.index(ids, id -> itemManager.getItemComposition(id).getName());
		keep.setIndex(index);
		log.debug("{} item names for Keep Items", index.size());
		refresh();
		return true;
	}

	/** The Keep Items setting changed: the player's edit, unless it's this plugin's own write. Client thread. */
	private void keepItemsEdited(String value)
	{
		String text = keepSync.edited(value, loadedKey);
		if (text != null)
		{
			keep.setText(text);
			reportUnknown();
			keepShown();
		}
	}

	/** Tells the player, in chat, which lines in Keep Items (names or wildcards) match no boss drop. */
	private void reportUnknown()
	{
		List<String> unknown = keep.unknown();
		if (!unknown.isEmpty())
		{
			chat("Keep Items has " + (unknown.size() == 1 ? "a line" : "lines")
				+ " that match no boss drop: " + quoted(unknown) + ". Check the spelling.");
		}
	}

	private static String quoted(List<String> lines)
	{
		return "\"" + String.join("\", \"", lines) + "\"";
	}

	/** A message from the plugin in the chatbox; none when logged out. */
	private void chat(String text)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(Names.DISPLAY + ": ")
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	// ---- Sidebar ----

	@Override
	public void showInBank()
	{
		clientThread.invoke(() ->
		{
			if (bankView.isBankOpen())
			{
				// Goes by whether the view is really showing (Bank Tags' open tag),
				// not by the button's words: showing, it goes back to the normal bank,
				// even when Bank Tags reopened it itself ("remember tab").
				openWithBank = false;
				setPending(false);
				toggleBankView();
			}
			else
			{
				// Pressed again while waiting: stop waiting.
				openWithBank = !openWithBank;
				setPending(openWithBank);
			}
		});
	}

	private void setPending(boolean waiting)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setPending(waiting);
			}
		});
	}

	@Override
	public void setListMode(ListMode mode)
	{
		configManager.setConfiguration(Names.CONFIG_GROUP, Names.KEY_LIST_MODE, mode);
	}

	@Override
	public void setGroupBy(GroupBy by)
	{
		configManager.setConfiguration(Names.CONFIG_GROUP, Names.KEY_GROUP_BY, by);
	}

	@Override
	public void openWiki(int itemId)
	{
		LinkBrowser.browse(WIKI_ITEM + itemId);
	}
}

package com.loosechange;

/**
 * Names in one place: the display name players read, and every name saved or
 * registered. Changing a saved name resets players' settings or Keep lists,
 * so once released it never changes without a migration of the old keys.
 */
final class Names
{
	/** The plugin's display name. Player-facing text only. */
	static final String DISPLAY = "Loose Change";

	/** Config group: settings, and per-account Keep list and bank copy. Never change. */
	static final String CONFIG_GROUP = "loosechange";
	/** The bank view's registered Bank Tags tag (and its layout key). Never change. */
	static final String BANK_TAG = "loosechange-sellable";

	/** Per-account (RS profile) config keys. Never change. */
	static final String KEY_KEEP = "keep";
	static final String KEY_BANK = "bank";
	/** Show: the setting, also set by the sidebar's Sellable / Whole bank switch. */
	static final String KEY_LIST_MODE = "listMode";
	/**
	 * The Keep Items setting: a copy of one account's Keep list (the {@link #KEY_KEEP}
	 * key), shown and edited in settings. Never change.
	 */
	static final String KEY_KEEP_ITEMS = "keepItems";
	/** Hidden setting: the RS profile whose Keep list {@link #KEY_KEEP_ITEMS} shows. Never change. */
	static final String KEY_KEEP_ITEMS_ACCOUNT = "keepItemsAccount";
	/** Group By: the setting, also set by the sidebar's Default / By boss / By type buttons. */
	static final String KEY_GROUP_BY = "groupBy";
	/** Show Drop Source: the sidebar rows' boss line. The sidebar alone, so a change doesn't lay the bank view out again. Never change. */
	static final String KEY_BOSS_LINE = "bossLine";
	/** Remember Bank View: off, the bank never opens on the view by itself. Lists nothing, so a change lays nothing out. Never change. */
	static final String KEY_REMEMBER_BANK_VIEW = "rememberBankView";
	/** The old List / By boss toggle (true = by boss), moved to {@link #KEY_GROUP_BY} once at startup. */
	static final String KEY_BY_BOSS_OLD = "byBoss";

	private Names()
	{
	}
}

package com.loosechange;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.config.ConfigManager;

/**
 * Which sidebar boxes the player folded or unfolded, kept in a hidden key
 * so they stay that way after a restart. Every
 * box starts open; the key holds the folded ones. Ids are a box's kind and
 * title ("boss:Vorkath", "type:Runes", "whole"). Older ids may still be in
 * the key and match no box now, so they do nothing: "kept" (the folded Kept
 * box that was at the bottom), and "sell" and "keptView" (the To Sell and
 * Kept boxes, which became plain boxes under the Sell / Keep strip on
 * 27 Nov). They're left as saved. Swing thread.
 */
final class PanelFolds
{
	/** Hidden key in the plugin's config group; not a setting, so no change to it relays the bank view out. */
	static final String KEY = "panelFolds";
	private static final String SEPARATOR = "|";

	/** Reads the saved folds (null for none). */
	private final Supplier<String> load;
	/** Saves the folds; null removes the key. */
	private final Consumer<String> save;
	private final Set<String> flipped = new LinkedHashSet<>();

	PanelFolds(Supplier<String> load, Consumer<String> save)
	{
		this.load = load;
		this.save = save;
		reload();
	}

	/** Kept in the plugin's config group, under {@link #KEY}. */
	static PanelFolds of(ConfigManager configManager)
	{
		return new PanelFolds(() -> configManager.getConfiguration(Names.CONFIG_GROUP, KEY), value ->
		{
			if (value == null)
			{
				configManager.unsetConfiguration(Names.CONFIG_GROUP, KEY);
			}
			else
			{
				configManager.setConfiguration(Names.CONFIG_GROUP, KEY, value);
			}
		});
	}

	/** Reads the current RuneLite profile's folds, after a profile switch too. */
	void reload()
	{
		flipped.clear();
		String saved = load.get();
		if (saved != null && !saved.isEmpty())
		{
			flipped.addAll(Arrays.asList(saved.split("\\" + SEPARATOR)));
		}
	}

	boolean isOpen(String id)
	{
		// Every box starts open; the key holds the ones folded.
		return !flipped.contains(id);
	}

	void toggle(String id)
	{
		if (!flipped.remove(id))
		{
			flipped.add(id);
		}
		save.accept(flipped.isEmpty() ? null : String.join(SEPARATOR, flipped));
	}
}

package com.loosechange;

import java.awt.AlphaComposite;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.DynamicGridLayout;

/**
 * The sidebar's stateless pieces: cards that stand where the list goes, the
 * plain box, small labels and helpers. Swing thread.
 */
final class PanelParts
{
	/** Card text width: Swing's HTML widths run wide, so this is less than the 189 px there is. */
	private static final int CARD_TEXT_WIDTH = 125;
	/** Getting Started: the step number's column, and the text beside it. */
	private static final int STEP_NUMBER_WIDTH = 10;
	private static final int STEP_TEXT_WIDTH = 134;

	private PanelParts()
	{
	}

	/** An icon, a bold line and one sentence, in a tile where the list goes. */
	static JComponent card(@Nullable BufferedImage icon, String title, String text)
	{
		JPanel c = new JPanel();
		c.setLayout(new BoxLayout(c, BoxLayout.Y_AXIS));
		c.setBackground(PanelStyle.BOX);
		c.setBorder(new EmptyBorder(14, 10, 13, 10));
		if (icon != null)
		{
			JLabel i = new JLabel(new ImageIcon(icon));
			i.setAlignmentX(Component.CENTER_ALIGNMENT);
			i.setBorder(new EmptyBorder(0, 0, 6, 0));
			c.add(i);
		}
		JLabel t = new JLabel(title);
		t.setFont(PanelStyle.BOLD);
		t.setForeground(Color.WHITE);
		t.setAlignmentX(Component.CENTER_ALIGNMENT);
		t.setBorder(new EmptyBorder(0, 0, 6, 0));
		c.add(t);
		JLabel body = new JLabel("<html><div style='text-align:center;width:" + CARD_TEXT_WIDTH + "px'>" + RowTooltip.escape(text) + "</div></html>");
		body.setFont(PanelStyle.REGULAR);
		body.setForeground(PanelStyle.LABEL);
		body.setAlignmentX(Component.CENTER_ALIGNMENT);
		c.add(body);
		return c;
	}

	/**
	 * Before any bank is seen: "Getting Started" and numbered steps,
	 * hairlines between. The first step, the one to do now, is white; the
	 * rest say what follows, in grey.
	 */
	static JComponent gettingStarted(String... steps)
	{
		JPanel c = new JPanel(new DynamicGridLayout(0, 1, 0, 0));
		c.setBackground(PanelStyle.BOX);
		c.setBorder(new EmptyBorder(10, 8, 4, 8));
		JLabel title = new JLabel("Getting Started");
		title.setFont(PanelStyle.TITLE_FONT);
		title.setForeground(Color.WHITE);
		title.setBorder(new EmptyBorder(0, 0, 9, 0));
		c.add(title);
		for (int i = 0; i < steps.length; i++)
		{
			JPanel step = new JPanel(new BorderLayout(8, 0));
			step.setOpaque(false);
			step.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, PanelStyle.RULE),
				new EmptyBorder(8, 0, 8, 0)));
			JLabel n = new JLabel(String.valueOf(i + 1));
			n.setFont(PanelStyle.BOLD);
			n.setForeground(PanelStyle.ACCENT);
			n.setVerticalAlignment(SwingConstants.TOP);
			n.setPreferredSize(new Dimension(STEP_NUMBER_WIDTH, n.getPreferredSize().height));
			step.add(n, BorderLayout.WEST);
			JLabel text = new JLabel("<html><div style='width:" + STEP_TEXT_WIDTH + "px'>" + RowTooltip.escape(steps[i]) + "</div></html>");
			text.setFont(PanelStyle.REGULAR);
			text.setForeground(i == 0 ? Color.WHITE : PanelStyle.LABEL);
			text.setVerticalAlignment(SwingConstants.TOP);
			step.add(text, BorderLayout.CENTER);
			c.add(step);
		}
		return c;
	}

	/** A box with no title bar, for a list the Sell / Keep strip titles. */
	static JPanel plainBox()
	{
		JPanel box = new JPanel(new DynamicGridLayout(0, 1, 0, 0));
		box.setBackground(PanelStyle.BOX);
		box.setBorder(new EmptyBorder(5, 8, 8, 8));
		return box;
	}

	/** A box title's count, in grey. */
	static JLabel count(int n)
	{
		JLabel l = new JLabel(Gp.exact(n));
		l.setFont(PanelStyle.REGULAR);
		l.setForeground(PanelStyle.LABEL);
		return l;
	}

	/**
	 * Empties a container quickly. RuneLite's window holds the game as a
	 * heavyweight canvas, so AWT works out the window's visible shape again
	 * for every component taken out of it, walking the neighbours each time:
	 * emptying Entire Bank's few thousand components that way froze the client
	 * for about 10 seconds. AWT skips that work for a component whose container
	 * is already marked invalid, so everything is marked first (top down, so
	 * each mark stops at its parent), then removed. The list is laid out again
	 * right after anyway.
	 */
	static void clear(JPanel container)
	{
		invalidateTree(container);
		container.removeAll();
	}

	private static void invalidateTree(Container c)
	{
		c.invalidate();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				invalidateTree((Container) child);
			}
		}
	}

	static BufferedImage faded(BufferedImage image, float alpha)
	{
		BufferedImage out = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return out;
	}

	static JMenuItem item(String text, Runnable action)
	{
		JMenuItem i = new JMenuItem(text);
		i.addActionListener(e -> action.run());
		return i;
	}
}

package com.loosechange;

import java.awt.Color;
import java.awt.Font;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The sidebar's look in one place:
 * Grand Exchange green for box titles, the grouping tabs' underline and
 * every gp value; dark greys for boxes and tiles; a
 * lighter grey fill for the selected half of a view switch.
 */
final class PanelStyle
{
	/** Box titles and the grouping tab's underline, the panel's only accent line. */
	static final Color ACCENT = ColorScheme.GRAND_EXCHANGE_PRICE;
	/** Gp values: the total, group totals and rows. */
	static final Color VALUE = ColorScheme.GRAND_EXCHANGE_PRICE;
	/** Labels under values, counts, second lines. */
	static final Color LABEL = ColorScheme.LIGHT_GRAY_COLOR;
	/** Quieter than labels: the price each, empty values, kept details. */
	static final Color QUIET = new Color(122, 122, 122);
	/** Boxes and tiles on the panel. */
	static final Color BOX = ColorScheme.DARKER_GRAY_COLOR;
	/** A row under the mouse, inside a box. */
	static final Color ROW_HOVER = new Color(38, 38, 38);
	/** The selected half of a view switch. */
	static final Color SELECTED = new Color(51, 51, 51);
	/** The button under the mouse. */
	static final Color BUTTON_HOVER = new Color(42, 42, 42);
	/** The hairline between rows in a box. */
	static final Color RULE = ColorScheme.DARK_GRAY_COLOR;

	static final Font TOTAL_FONT = FontManager.getRunescapeBoldFont().deriveFont(24f);
	static final Font TILE_FONT = FontManager.getRunescapeBoldFont().deriveFont(20f);
	static final Font TITLE_FONT = FontManager.getRunescapeBoldFont().deriveFont(18f);
	static final Font BOLD = FontManager.getRunescapeBoldFont();
	static final Font REGULAR = FontManager.getRunescapeFont();
	static final Font SMALL = FontManager.getRunescapeSmallFont();

	private PanelStyle()
	{
	}

	/** A group's title as shown, in Title Case like the rest of the panel:"Boss loot" reads "Boss Loot". */
	static String groupTitle(String title)
	{
		return SellList.BOSS_LOOT.equals(title) ? "Boss Loot" : title;
	}
}

package com.loosechange;

import java.awt.Color;
import java.util.List;

/**
 * A sidebar row's hover: the name, then label and value lines that line
 * up, then the bosses that drop it, one a line. A Swing HTML table. The bank
 * view keeps the game tooltip's plain lines ({@link ItemInfo}).
 */
final class RowTooltip
{
	private static final String WHITE = "#ffffff";
	private static final String ALCH = hex(ViewOverlay.ALCH_COLOR);

	private RowTooltip()
	{
	}

	/** A row for sale (or part kept). */
	static String forSale(SellList.Row row, boolean ironman, boolean showAlch)
	{
		StringBuilder sb = start(row.getName());
		line(sb, "Sell", Gp.exact(row.getSellQuantity()) + " × " + Gp.exact(row.getUnitValue()), null);
		line(sb, ironman ? "High Alch" : "After GE Tax", Gp.format(row.sellValue()), hex(PanelStyle.VALUE));
		if (row.getKeptQuantity() > 0)
		{
			line(sb, "Keeping", Gp.exact(row.getKeptQuantity()), null);
		}
		if (showAlch && row.isAlchBetter())
		{
			whole(sb, "Worth more alched than sold", ALCH);
		}
		droppers(sb, row.getSources());
		return end(sb);
	}

	/** A row in the Keep list. */
	static String kept(SellList.Row row)
	{
		StringBuilder sb = start(row.getName());
		line(sb, "Keeping", Gp.exact(row.getKeptQuantity()), null);
		line(sb, "Worth", Gp.format(row.getUnitValue() * row.getKeptQuantity()), null);
		whole(sb, "In Keep Items (settings). Right-click:", hex(PanelStyle.QUIET));
		whole(sb, "Sell Anyway to list it again", hex(PanelStyle.QUIET));
		return end(sb);
	}

	/** An Entire Bank row: the stack at GE prices before tax, and who drops it when it's a sellable drop. */
	static String worth(BankWorth.Row row, SellList.Row sellable)
	{
		StringBuilder sb = start(row.getName());
		line(sb, "Stack", Gp.exact(row.getQuantity()) + " × " + Gp.exact(row.getPrice()), null);
		line(sb, "GE Value", Gp.format(row.value()), hex(PanelStyle.VALUE));
		if (sellable != null)
		{
			droppers(sb, sellable.getSources());
		}
		return end(sb);
	}

	private static StringBuilder start(String name)
	{
		StringBuilder sb = new StringBuilder("<html><table cellpadding=0 cellspacing=0>");
		whole(sb, name, WHITE);
		return sb;
	}

	private static String end(StringBuilder sb)
	{
		return sb.append("</table></html>").toString();
	}

	private static void droppers(StringBuilder sb, List<String> sources)
	{
		if (sources.isEmpty())
		{
			return;
		}
		sb.append("<tr><td colspan=3 style='padding-top:3px'><font color='").append(hex(PanelStyle.QUIET))
			.append("'>Dropped by</font></td></tr>");
		int shown = Math.min(sources.size(), ItemInfo.MAX_SOURCES);
		for (int i = 0; i < shown; i++)
		{
			whole(sb, sources.get(i), null);
		}
		if (sources.size() > shown)
		{
			whole(sb, "and " + (sources.size() - shown) + " more", hex(PanelStyle.QUIET));
		}
	}

	/** A label on the left and its value on the right. */
	private static void line(StringBuilder sb, String label, String value, String valueColor)
	{
		sb.append("<tr><td><font color='").append(hex(PanelStyle.LABEL)).append("'>").append(escape(label))
			.append("</font></td><td width=10></td><td align=right>");
		color(sb, value, valueColor);
		sb.append("</td></tr>");
	}

	/** A line across both columns. */
	private static void whole(StringBuilder sb, String text, String color)
	{
		sb.append("<tr><td colspan=3>");
		color(sb, text, color);
		sb.append("</td></tr>");
	}

	private static void color(StringBuilder sb, String text, String color)
	{
		if (color == null)
		{
			sb.append(escape(text));
		}
		else
		{
			sb.append("<font color='").append(color).append("'>").append(escape(text)).append("</font>");
		}
	}

	static String hex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.loosechange;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import javax.annotation.Nullable;

/**
 * The sidebar search's matching, shared
 * by the sidebar and, with Search Bank View on, the bank view. A query is
 * trimmed and lower-cased ({@link #normalize}); "" matches all. Pure, so it's
 * unit tested.
 */
final class Search
{
	private Search()
	{
	}

	static String normalize(String text)
	{
		return text == null ? "" : KeepList.key(text);
	}

	/**
	 * Whether an item matches: its name, or the boss it's listed under,
	 * contains the query in any case. Only that one boss, the one the player
	 * sees: Rune kiteshield came up for "dragon" through King Black Dragon,
	 * one of 26 bosses that drop it, while its line said Fortis Colosseum. A
	 * {@code *} works as in Keep Items, on the name, so what's listed is what
	 * Keep would keep.
	 *
	 * @param boss the boss it's listed under ("" or null for none)
	 */
	static boolean matches(String query, String name, @Nullable String boss)
	{
		if (query.isEmpty())
		{
			return true;
		}
		String key = KeepList.key(name);
		if (KeepList.isWildcard(query))
		{
			return KeepList.wildcard(query).matcher(key).matches();
		}
		return key.contains(query) || boss != null && KeepList.key(boss).contains(query);
	}

	/**
	 * The boss each row is listed under: its boss line, or with Group By Boss
	 * its box. They differ only when Shared Drops is Most Loot, which can put
	 * a shared drop under a boss other than its likeliest; the box title is
	 * then the only boss shown, so a search for it finds the whole box.
	 */
	static Function<SellList.Row, String> listedBoss(SellList.Result r, GroupBy by, SharedItems shared)
	{
		if (by != GroupBy.BOSS || shared != SharedItems.BIGGEST_GROUP)
		{
			return SellList.Row::topSource;
		}
		Map<Integer, String> boss = new HashMap<>();
		for (SellList.Group g : r.groups(by, shared))
		{
			for (SellList.Row row : g.getRows())
			{
				boss.put(row.getItemId(), g.getTitle());
			}
		}
		// Kept rows aren't grouped: their boss line.
		return row -> boss.getOrDefault(row.getItemId(), row.topSource());
	}

	/** The rows the query matches, in their order; the same list when it's "". */
	static List<SellList.Row> rows(String query, List<SellList.Row> rows, Function<SellList.Row, String> bossOf)
	{
		if (query.isEmpty())
		{
			return rows;
		}
		List<SellList.Row> out = new ArrayList<>();
		for (SellList.Row row : rows)
		{
			if (matches(query, row.getName(), bossOf.apply(row)))
			{
				out.add(row);
			}
		}
		return out;
	}

	/** {@link #rows(String, List, Function)} with each row's boss line. */
	static List<SellList.Row> rows(String query, List<SellList.Row> rows)
	{
		return rows(query, rows, SellList.Row::topSource);
	}

	/** The sell list cut to the matches, for sale and kept. Its totals stay the whole list's. */
	static SellList.Result filter(String query, SellList.Result r, Function<SellList.Row, String> bossOf)
	{
		if (query.isEmpty())
		{
			return r;
		}
		return new SellList.Result(rows(query, r.getSellable(), bossOf), rows(query, r.getKept(), bossOf), r.getTotalValue(),
			r.getSlotsFreed(), r.isIronman());
	}

	/** {@link #filter(String, SellList.Result, Function)} with each row's boss line. */
	static SellList.Result filter(String query, SellList.Result r)
	{
		return filter(query, r, SellList.Row::topSource);
	}

	/**
	 * The whole bank cut to the matches. A stack's boss comes from the drop
	 * list ({@code drops}, for sale or kept); anything else matches by name.
	 */
	static BankWorth.Result filter(String query, BankWorth.Result w, SellList.Result drops)
	{
		if (query.isEmpty())
		{
			return w;
		}
		Map<Integer, SellList.Row> byId = byId(drops);
		List<BankWorth.Row> out = new ArrayList<>();
		for (BankWorth.Row row : w.getRows())
		{
			SellList.Row drop = byId.get(row.getItemId());
			if (matches(query, row.getName(), drop == null ? null : drop.topSource()))
			{
				out.add(row);
			}
		}
		return new BankWorth.Result(out, w.getTotalValue());
	}

	/** Every drop list row by item id, for sale or kept (an item is never both). */
	static Map<Integer, SellList.Row> byId(SellList.Result drops)
	{
		Map<Integer, SellList.Row> byId = new HashMap<>();
		for (SellList.Row row : drops.getKept())
		{
			byId.put(row.getItemId(), row);
		}
		for (SellList.Row row : drops.getSellable())
		{
			byId.put(row.getItemId(), row);
		}
		return byId;
	}
}

package com.loosechange;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;
import lombok.Builder;
import lombok.Value;

/**
 * Works out what in the bank could be sold: boss and raid drops that are
 * tradeable, worth at least the threshold after GE tax, and not kept.
 * Pure: item facts come in through {@link Item}, so it runs in unit tests.
 */
final class SellList
{
	/** What the plugin knows about an item (from ItemManager in game). */
	@Value
	static class Item
	{
		String name;
		boolean tradeable;
		/** RuneLite's GE price. */
		long gePrice;
		/** High Level Alchemy value. */
		int alchPrice;
	}

	@Value
	@Builder
	static class Settings
	{
		boolean includeRare;
		/** Supply groups left out (ticked under Hide Drops). */
		@Builder.Default
		Set<BossDrops.Category> hidden = Collections.emptySet();
		/** Stacks worth less than this (before tax) are left out. */
		long hideUnder;
		/** Items worth more than this each (before tax) are left out; 0 leaves none out. */
		long hideOver;
		/** Ironmen can't use the GE, so items are valued at high alch. */
		boolean ironman;
		@Builder.Default
		SortBy sort = SortBy.STACK_VALUE;
	}

	/** One bank stack that's up for sale or kept (Keep keeps the whole stack). */
	@Value
	static class Row
	{
		int itemId;
		String name;
		/** The whole stack in the bank. */
		int quantity;
		int sellQuantity;
		int keptQuantity;
		/** One item's worth: after GE tax, or high alch for ironmen. */
		long unitValue;
		/** The bosses that drop it, most common drop first. */
		List<String> sources;
		/** High alch beats selling on the GE after tax. */
		boolean alchBetter;
		/** Its Hide Drops group, or null for boss loot (gear, uniques, anything else). */
		BossDrops.Category category;

		long sellValue()
		{
			return unitValue * sellQuantity;
		}

		/** Selling it frees a bank slot (nothing of it is kept). */
		boolean freesSlot()
		{
			return keptQuantity == 0;
		}

		String topSource()
		{
			return sources.isEmpty() ? "" : sources.get(0);
		}
	}

	/** A titled group of sellable items: a boss and what it drops, or a type of item. */
	@Value
	static class Group
	{
		String title;
		List<Row> rows;
		long value;
	}

	/** The title of the type group for items in no Hide Drops group. */
	static final String BOSS_LOOT = "Boss loot";

	@Value
	static class Result
	{
		/** For sale, in the Sort By order. */
		List<Row> sellable;
		/** Every stack with something kept, in the Sort By order (by the whole stack's value). */
		List<Row> kept;
		long totalValue;
		int slotsFreed;
		boolean ironman;

		static final Result EMPTY = new Result(Collections.emptyList(), Collections.emptyList(), 0, 0, false);

		/**
		 * The sellable items in groups, items in the list's order, each item
		 * in one group, so the groups add up to {@link #getTotalValue()}. By
		 * type, its Hide Drops group (or boss loot); by boss, the boss that
		 * {@code shared} picks. Groups with the most to sell come first.
		 *
		 * @param by BOSS or TYPE
		 */
		List<Group> groups(GroupBy by, SharedItems shared)
		{
			Map<String, List<Row>> groups = new LinkedHashMap<>();
			for (Row row : sellable)
			{
				if (by == GroupBy.TYPE)
				{
					add(groups, row.getCategory() == null ? BOSS_LOOT : row.getCategory().toString(), row);
				}
				else if (shared == SharedItems.MOST_COMMON)
				{
					add(groups, row.topSource(), row);
				}
				else
				{
					for (String source : row.getSources())
					{
						add(groups, source, row);
					}
				}
			}
			List<Group> out = toGroups(groups);
			if (by == GroupBy.BOSS && shared == SharedItems.BIGGEST_GROUP)
			{
				out.sort(GROUPS_BY_VALUE);
				out = onePlaceEach(out);
			}
			out.sort(GROUPS_BY_VALUE);
			return out;
		}

		private static void add(Map<String, List<Row>> groups, String title, Row row)
		{
			groups.computeIfAbsent(title, k -> new ArrayList<>()).add(row);
		}
	}

	private static List<Group> toGroups(Map<String, List<Row>> groups)
	{
		List<Group> out = new ArrayList<>(groups.size());
		for (Map.Entry<String, List<Row>> e : groups.entrySet())
		{
			out.add(new Group(e.getKey(), e.getValue(), valueOf(e.getValue())));
		}
		return out;
	}

	private static long valueOf(List<Row> rows)
	{
		long value = 0;
		for (Row row : rows)
		{
			value += row.sellValue();
		}
		return value;
	}

	/**
	 * Each item under the first group that lists it (biggest first); groups
	 * left empty are dropped, the rest valued by what's left under them.
	 */
	static List<Group> onePlaceEach(List<Group> groups)
	{
		Set<Integer> placed = new HashSet<>();
		List<Group> out = new ArrayList<>();
		for (Group group : groups)
		{
			List<Row> rows = new ArrayList<>();
			for (Row row : group.getRows())
			{
				if (placed.add(row.getItemId()))
				{
					rows.add(row);
				}
			}
			if (!rows.isEmpty())
			{
				out.add(new Group(group.getTitle(), rows, valueOf(rows)));
			}
		}
		return out;
	}

	private static final Comparator<Row> BY_SELL_VALUE = Comparator
		.comparingLong(Row::sellValue).reversed()
		.thenComparing(Row::getName);
	private static final Comparator<Row> BY_STACK_VALUE = Comparator
		.comparingLong((Row r) -> r.getUnitValue() * r.getQuantity()).reversed()
		.thenComparing(Row::getName);
	private static final Comparator<Row> BY_UNIT_VALUE = Comparator
		.comparingLong(Row::getUnitValue).reversed()
		.thenComparing(Row::getName);
	/** Groups with the most to sell first. */
	private static final Comparator<Group> GROUPS_BY_VALUE = Comparator
		.comparingLong(Group::getValue).reversed()
		.thenComparing(Group::getTitle);

	private static Comparator<Row> sellOrder(SortBy sort)
	{
		return sort == SortBy.ITEM_VALUE ? BY_UNIT_VALUE : BY_SELL_VALUE;
	}

	private static Comparator<Row> keptOrder(SortBy sort)
	{
		return sort == SortBy.ITEM_VALUE ? BY_UNIT_VALUE : BY_STACK_VALUE;
	}

	private SellList()
	{
	}

	/**
	 * @param bank  item id to quantity, already canonical (unnoted, no placeholders)
	 * @param items item facts by id; null when unknown
	 */
	static Result compute(Map<Integer, Integer> bank, BossDrops drops, IntFunction<Item> items, KeepList keep, Settings settings)
	{
		List<Row> sellable = new ArrayList<>();
		List<Row> kept = new ArrayList<>();
		long total = 0;
		int slots = 0;

		for (Map.Entry<Integer, Integer> e : bank.entrySet())
		{
			int id = e.getKey();
			int quantity = e.getValue();
			if (quantity <= 0)
			{
				continue;
			}
			List<BossDrops.Source> sources = drops.sourcesOf(id, settings.isIncludeRare());
			if (sources.isEmpty() || settings.getHidden().contains(drops.categoryOf(id)))
			{
				continue;
			}
			Item item = items.apply(id);
			if (item == null || !item.isTradeable())
			{
				continue;
			}

			long geValue = GeTax.afterTax(id, item.getGePrice());
			long unit = settings.isIronman() ? item.getAlchPrice() : geValue;
			if (unit <= 0)
			{
				continue;
			}

			int keptQuantity = keep.keptOf(id, quantity);
			List<String> names = new ArrayList<>(sources.size());
			for (BossDrops.Source s : sources)
			{
				names.add(s.getName());
			}
			Row row = new Row(id, item.getName(), quantity, quantity - keptQuantity, keptQuantity, unit,
				Collections.unmodifiableList(names), !settings.isIronman() && item.getAlchPrice() > geValue, drops.categoryOf(id));

			if (keptQuantity > 0)
			{
				kept.add(row);
			}
			// The filters go by what players see the item worth: GE price before tax (high alch for ironmen).
			long price = settings.isIronman() ? item.getAlchPrice() : item.getGePrice();
			boolean tooValuable = settings.getHideOver() > 0 && price > settings.getHideOver();
			boolean tooSmall = price * row.getSellQuantity() < settings.getHideUnder();
			if (row.getSellQuantity() > 0 && !tooSmall && !tooValuable)
			{
				sellable.add(row);
				total += row.sellValue();
				if (row.freesSlot())
				{
					slots++;
				}
			}
		}

		sellable.sort(sellOrder(settings.getSort()));
		kept.sort(keptOrder(settings.getSort()));
		return new Result(Collections.unmodifiableList(sellable), Collections.unmodifiableList(kept), total, slots, settings.isIronman());
	}
}

package com.loosechange;

import lombok.RequiredArgsConstructor;

/**
 * By boss, which boss an item several bosses drop goes under (Shared Drops).
 * Each item shows once, in the sidebar and the bank view alike. Saved by
 * name, so never rename a constant.
 */
@RequiredArgsConstructor
public enum SharedItems
{
	/** The boss with the most to sell, counting every item it drops. First, as it's the default. */
	BIGGEST_GROUP("Most Loot"),
	/** The boss most likely to have dropped it: its best drop rate, the first boss its hover names. */
	MOST_COMMON("Drop Rate");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.loosechange;

import lombok.RequiredArgsConstructor;

/** The order of the list and the bank view (Sort By). Saved by name, so never rename a constant. */
@RequiredArgsConstructor
public enum SortBy
{
	/** What the stack sells for, highest first. */
	STACK_VALUE("Stack Value"),
	/** What one item is worth, highest first. */
	ITEM_VALUE("Value Per");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.loosechange;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/**
 * The sidebar's two top tiles, the total and Show in Bank, side by side,
 * 4 px apart, widths 1.3 : 1 whatever they hold, both as tall as the taller.
 */
final class TileLayout implements LayoutManager
{
	private static final int GAP = 4;
	private static final double LEFT = 1.3 / 2.3;

	@Override
	public void layoutContainer(Container parent)
	{
		Insets in = parent.getInsets();
		int w = parent.getWidth() - in.left - in.right - GAP;
		int h = parent.getHeight() - in.top - in.bottom;
		int left = (int) Math.round(w * LEFT);
		Component[] c = parent.getComponents();
		c[0].setBounds(in.left, in.top, left, h);
		c[1].setBounds(in.left + left + GAP, in.top, w - left, h);
	}

	@Override
	public Dimension preferredLayoutSize(Container parent)
	{
		Insets in = parent.getInsets();
		int w = GAP;
		int h = 0;
		for (Component c : parent.getComponents())
		{
			Dimension d = c.getPreferredSize();
			w += d.width;
			h = Math.max(h, d.height);
		}
		return new Dimension(w + in.left + in.right, h + in.top + in.bottom);
	}

	@Override
	public Dimension minimumLayoutSize(Container parent)
	{
		return preferredLayoutSize(parent);
	}

	@Override
	public void addLayoutComponent(String name, Component comp)
	{
	}

	@Override
	public void removeLayoutComponent(Component comp)
	{
	}
}

