import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * On items in the bank view: the Alch Tag (the High Level Alchemy icon or
 * the word Alch), and what the item is worth and who drops it on hover.
 */
class ViewOverlay extends WidgetItemOverlay
{
	static final Color ALCH_COLOR = new Color(255, 176, 60);
	/** The icon fits this square, scaled by whole steps only so it stays sharp (IconFit). */
	private static final int ICON_BOX = 16;

	private final Client client;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;
	private final BankView bankView;
	private final TextComponent label = new TextComponent();

	/** The view's items for sale by canonical id. */
	private volatile Map<Integer, SellList.Row> rows = Collections.emptyMap();
	/** Every priced stack by canonical id in Whole bank mode; null in Sellable mode. */
	private volatile Map<Integer, BankWorth.Row> worth;
	private volatile AlchMark alchMark = AlchMark.OFF;
	private volatile boolean ironman;
	private volatile BufferedImage alchIcon;

	@Inject
	ViewOverlay(Client client, ItemManager itemManager, TooltipManager tooltipManager, BankView bankView, SpriteManager spriteManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		this.bankView = bankView;
		showOnBank();
		label.setColor(ALCH_COLOR);
		label.setText("Alch");
		spriteManager.getSpriteAsync(SpriteID.Magicon.HIGH_LEVEL_ALCHEMY, 0,
			sprite -> alchIcon = IconFit.fit(sprite, ICON_BOX));
	}

	/** The High Level Alchemy icon, once loaded; null before. */
	BufferedImage getAlchIcon()
	{
		return alchIcon;
	}

	/**
	 * @param worth every priced stack by canonical id in Whole bank mode
	 *              (the hover shows its worth); null in Sellable mode
	 */
	void update(Map<Integer, SellList.Row> rows, Map<Integer, BankWorth.Row> worth, AlchMark alchMark, boolean ironman)
	{
		this.rows = rows;
		this.worth = worth;
		this.alchMark = alchMark;
		this.ironman = ironman;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!bankView.isOpen())
		{
			return;
		}
		int id = itemManager.canonicalize(itemId);
		SellList.Row row = rows.get(id);
		Map<Integer, BankWorth.Row> whole = worth;
		BankWorth.Row worthRow = whole == null ? null : whole.get(id);
		if (row == null && worthRow == null)
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();

		if (row != null && row.isAlchBetter() && !ironman)
		{
			drawAlchMark(graphics, bounds);
		}

		Point mouse = client.getMouseCanvasPosition();
		if (!client.isMenuOpen() && bounds.contains(mouse.getX(), mouse.getY()))
		{
			List<String> lines = whole != null
				? (worthRow == null ? List.of() : ItemInfo.worthLines(worthRow, row))
				: ItemInfo.lines(row, ironman, alchMark != AlchMark.OFF);
			if (!lines.isEmpty())
			{
				tooltipManager.add(new Tooltip(String.join("</br>", lines)));
			}
		}
	}

	/** Bottom right, clear of the quantity (top left) and other plugins' labels (bottom left). */
	private void drawAlchMark(Graphics2D graphics, Rectangle bounds)
	{
		switch (alchMark)
		{
			case ICON:
				BufferedImage icon = alchIcon;
				if (icon != null)
				{
					graphics.drawImage(icon, bounds.x + bounds.width - icon.getWidth(), bounds.y + bounds.height - icon.getHeight(), null);
				}
				break;
			case LABEL:
				graphics.setFont(FontManager.getRunescapeSmallFont());
				FontMetrics fm = graphics.getFontMetrics();
				label.setPosition(new java.awt.Point(bounds.x + bounds.width - fm.stringWidth("Alch"), bounds.y + bounds.height));
				label.render(graphics);
				break;
			default:
				break;
		}
	}
}

